-- Guest Hub «مركز الضيوف» — session H6 (14 Nov 2026; docs/guest-hub/GUEST-HUB-SPEC.md §1.8 gate 5, §2.9, §2.10, §4.7,
-- §4.8, §4.9, §5.4, §5.6, §5.7, §7.3, §7.5; DECISIONS.md 2026-11-14 «Guest Hub H6»). Generated by
-- scripts/hub-lab-migration.mjs from scripts/hub-lab-migration.src.sql, tests/hub-bank/seed.jsonl and the H5 function
-- public.hub_knowledge_for — never edited once applied (CLAUDE.md §12).
--   1. The test lab: hub_test_items (the bank, seeded with the 102 questions of tests/hub-bank/seed.jsonl — the Wi-Fi
--      passwords are never in it: {card:<id>} is read at run time), hub_eval_runs + hub_eval_results; hub_eval_plan /
--      hub_eval_start (as the user, through hub-admin eval_run: the estimated cost first, refused past the budget cap,
--      one run at a time), hub_eval_claim / hub_eval_finish / hub_eval_context / hub_knowledge_for_eval (service role —
--      hub-agent runs the items through the real engine in test mode: nothing sent, nothing stored but the results);
--      grading is code (_shared/hub/grade.ts) — a model never decides pass or fail.
--   2. The gate (spec §4.8): «نشر» in «قاعدة المعرفة» and of a persona needs a finished gate run on the candidate whose
--      verdict is pass — an item that passes on the live configuration and fails on the candidate (after one retry)
--      blocks, with the list; items failing on both are known gaps and do not block. hub_knowledge_publish(p_dry_run,
--      p_eval_run) replaces the H4 function; internal.hub_knowledge_gate checks the run.
--   3. The shadow gate (spec §1.8 gate 5): internal.hub_test_lab_ready — the unit's latest full run (manual or baseline)
--      has no failing item other than a known gap («فجوة معروفة», set by a person). «بموافقة الفريق» and «يرد تلقائيًا»
--      may now be chosen (assistant: edit, Ahmed's H6 brief); every other gate stays.
--   4. The persona (spec §2.9, prompts.md §5): hub_persona_save (the draft) and hub_persona_publish (through the gate).
--   5. Licences (spec §2.10, §5.6 item 4): hub_licence_set needs a reason; hub_licence_rows (the last 30 days'
--      counters, information only); hub_flag_wrong (a sent reply flagged wrong → the counters, «لم أعرف الإجابة», one
--      alert to the admins by email and in «التنبيهات»).
--   6. The radar (spec §5.7): hub_turns.topics / topic_hint / outcome (codes, kept after the understanding is purged),
--      hub_radar, the spike alert (pg_cron hub-radar hourly → hub_radar_tick), proposed topics (hub_topic_hints,
--      hub_topic_hint_decide).
--   7. Draft cards from staff replies (Ahmed, 14 Nov 2026; prompts.md §7): a staff reply in a conversation with an open
--      «لم أعرف الإجابة» entry queues a job (hub_card_jobs); hub-agent writes the draft (claude-sonnet-5-5, hub_models
--      draft_card) — never published by itself, linked to the entry; price_note kept apart.
-- Nothing is switched on or off here: every unit keeps its mode, every licence its mode.

select set_config('app.actor', 'migration', true);

-- ───────────────────────────────────────────── 0. what existing objects gain ─────────────────────────────────────────────

alter table public.hub_usage_daily drop constraint hub_usage_daily_layer_check;
alter table public.hub_usage_daily add constraint hub_usage_daily_layer_check check (layer in ('understand', 'tag', 'compose', 'translate', 'suggest', 'draft_card'));
alter table public.hub_usage_daily drop constraint hub_usage_daily_source_check;
-- simulator: «المحاكي» — counted in the budget, shown apart from the test lab
alter table public.hub_usage_daily add constraint hub_usage_daily_source_check check (source in ('turn', 'staff', 'test_lab', 'simulator'));

alter table public.hub_alerts drop constraint hub_alerts_kind_check;
alter table public.hub_alerts add constraint hub_alerts_kind_check
  check (kind in ('budget_pct', 'budget_cap', 'portfolio_pct', 'quality_drop', 'offer_ending', 'card_expiring', 'spike', 'escalation', 'complaint',
                  'webhook_silent', 'template_rejected', 'api_credit', 'flagged_wrong'));
alter table public.hub_conversation_events drop constraint hub_conversation_events_kind_check;
alter table public.hub_conversation_events add constraint hub_conversation_events_kind_check
  check (kind in ('state', 'owner', 'handoff', 'transfer', 'pause', 'resume', 'approve', 'reject', 'licence', 'booking', 'order', 'close', 'cancel_word',
                  'block', 'unanswered', 'test', 'flag'));

-- a sent assistant reply flagged wrong (spec §3.4 hub_flag_wrong)
alter table public.hub_messages add column flagged_wrong_at timestamptz;
alter table public.hub_messages add column flagged_wrong_by uuid references auth.users (id) on delete set null;

-- the draft cards written from a staff reply: the price the reply stated (never in the card's text) and where it came from
alter table public.hub_knowledge_cards add column price_note text check (price_note is null or char_length(price_note) <= 300);
alter table public.hub_knowledge_cards add column draft_origin jsonb check (draft_origin is null or jsonb_typeof(draft_origin) = 'object');
comment on column public.hub_knowledge_cards.price_note is 'Guest Hub H6: a draft card written from a staff reply keeps the price that reply stated here, never in the card text (prompts.md §7); shown apart in the editor; never read by the engine.';
alter table public.hub_unanswered add column draft_card_id uuid references public.hub_knowledge_cards (id) on delete set null;

-- the draft card's model (prompts.md §7): claude-sonnet-5-5 (Ahmed, 14 Nov 2026)
update public.settings set value = value || '{"draft_card": "claude-sonnet-5-5"}'::jsonb where key = 'hub_models' and not (value ? 'draft_card');

-- the library view (H4) again, so it carries the two new columns (a view keeps the columns it was created with)
drop view public.hub_cards_library;
create view public.hub_cards_library with (security_invoker = true) as
  select c.*, internal.hub_card_pending(c) as pending, internal.hub_card_check(c) as "check",
         case when c.status = 'archived' then 'archived'
              when c.live is null then 'draft'
              when (c.live ->> 'expires_on') is not null and (c.live ->> 'expires_on')::date < internal.riyadh_today() then 'expired'
              else 'published' end as state,
         (select s.full_name from public.staff s where s.user_id = c.verified_by) as verified_by_name
    from public.hub_knowledge_cards c;
comment on view public.hub_cards_library is 'hub_knowledge_cards + pending + check + state (draft | published | expired | archived) + the verifier''s name. RLS of the cards applies (security invoker). H6: + price_note, draft_origin.';
revoke all on public.hub_cards_library from public, anon, authenticated;
grant select on public.hub_cards_library to authenticated, service_role;

-- ───────────────────────────────────────────── 1. the bank ─────────────────────────────────────────────

create table public.hub_test_items (
  id uuid primary key default gen_random_uuid(),
  -- q001 … from the seed; s-… from staff and the simulator
  key text not null unique check (key ~ '^[a-z][a-z0-9-]{1,40}$'),
  unit_key text not null references public.hub_units (key) on update cascade,
  language text not null check (language in ('ar', 'en')),
  -- one or more guest turns (test text — never a real guest's words)
  messages jsonb not null check (jsonb_typeof(messages) = 'array' and jsonb_array_length(messages) between 1 and 10),
  context jsonb not null default '{}'::jsonb check (jsonb_typeof(context) = 'object'),
  -- action (answer | ask | quote | handoff | booking_status | refuse | third_language | greeting | send_summary |
  -- cancel_word_question | opt_out), cards, faq, must_include, must_not_include, state
  expect jsonb not null check (jsonb_typeof(expect) = 'object' and expect ? 'action'),
  note text check (note is null or char_length(note) <= 500),
  tags text[] not null default '{}',
  status text not null default 'active' check (status in ('active', 'retired')),
  added_from text not null default 'seed' check (added_from in ('seed', 'queue', 'staff', 'simulator')),
  -- «فجوة معروفة» — set by a person; a known gap never blocks the shadow gate
  known_gap_at timestamptz,
  known_gap_by uuid references auth.users (id) on delete set null,
  known_gap_reason text check (known_gap_reason is null or char_length(known_gap_reason) <= 300),
  sort integer not null default 0,
  created_by uuid references auth.users (id) on delete set null,
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
comment on table public.hub_test_items is '«مركز الضيوف» the test bank (spec §4.8): test questions per unit with the expected action, cards, phrases and state; seeded from tests/hub-bank/seed.jsonl (H6, 14 Nov 2026).';
create trigger hub_test_items_touch before update on public.hub_test_items for each row execute function internal.stamp();
create trigger hub_test_items_audit after insert or update or delete on public.hub_test_items
  for each row execute function internal.audit('key', 'unit_key', 'language', 'status', 'known_gap_at', 'known_gap_reason', 'added_from', 'is_test');

create table public.hub_eval_runs (
  id uuid primary key default gen_random_uuid(),
  -- manual / baseline = the whole bank of the units on the live configuration; knowledge / persona = a publish gate
  trigger text not null check (trigger in ('manual', 'baseline', 'knowledge', 'persona')),
  units text[] not null,
  status text not null default 'queued' check (status in ('queued', 'running', 'done', 'failed', 'cancelled')),
  -- the candidate: {cards: [uuid], cards_hash} (knowledge) or {unit, persona, persona_hash} (persona)
  candidate jsonb check (candidate is null or jsonb_typeof(candidate) = 'object'),
  -- the live configuration the run judged (internal.hub_live_hash) and the engine's version (set by the function)
  live_hash text not null,
  engine text check (engine is null or engine ~ '^[a-z0-9._-]{1,80}$'),
  baseline_run_id uuid references public.hub_eval_runs (id) on delete set null,
  items_total integer not null default 0,
  items_done integer not null default 0,
  passed integer not null default 0,
  failed integer not null default 0,
  errors integer not null default 0,
  est_cost_usd numeric(12, 6) not null default 0,
  cost_usd numeric(12, 6) not null default 0,
  verdict text check (verdict is null or verdict in ('pass', 'blocked', 'failed')),
  -- codes only: [{key, unit}] — what blocked; the known gaps (fail on both, or flagged)
  blocked_items jsonb not null default '[]'::jsonb,
  known_gaps jsonb not null default '[]'::jsonb,
  stop_reason text check (stop_reason is null or stop_reason ~ '^[a-z_]{2,40}$'),
  requested_by uuid references auth.users (id) on delete set null,
  started_at timestamptz,
  finished_at timestamptz,
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
comment on table public.hub_eval_runs is '«مركز الضيوف» test-lab runs (spec §4.8): the bank through the real engine in test mode; the verdict of a publish gate.';
create trigger hub_eval_runs_touch before update on public.hub_eval_runs for each row execute function internal.stamp();
create unique index hub_eval_runs_one_active on public.hub_eval_runs ((true)) where status in ('queued', 'running') and not is_test;

create table public.hub_eval_results (
  id uuid primary key default gen_random_uuid(),
  run_id uuid not null references public.hub_eval_runs (id) on delete cascade,
  item_id uuid not null references public.hub_test_items (id) on delete cascade,
  config text not null check (config in ('live', 'candidate')),
  attempt integer not null default 1 check (attempt between 1 and 3),
  status text not null default 'pending' check (status in ('pending', 'running', 'pass', 'fail', 'error', 'skipped')),
  -- codes only (grade.ts): action, state, card, faq, must_include, must_not_include, guard, language, error …
  reasons text[] not null default '{}',
  -- the replies the engine composed for the test question (test text; the Wi-Fi cards' text may be in it — never
  -- written to a file or a log)
  replies jsonb not null default '[]'::jsonb check (jsonb_typeof(replies) = 'array'),
  -- the codes of the outcome: kind, state, transitions, topics, the card keys used, the guard's refusals
  outcome jsonb,
  cost_usd numeric(12, 6) not null default 0,
  claimed_at timestamptz,
  finished_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (run_id, item_id, config)
);
create trigger hub_eval_results_touch before update on public.hub_eval_results for each row execute function internal.stamp();
create index hub_eval_results_pending on public.hub_eval_results (created_at) where status in ('pending', 'running');

alter table public.hub_test_items enable row level security;
alter table public.hub_eval_runs enable row level security;
alter table public.hub_eval_results enable row level security;
revoke all on table public.hub_test_items, public.hub_eval_runs, public.hub_eval_results from public, anon, authenticated;
grant select on table public.hub_test_items, public.hub_eval_runs, public.hub_eval_results to authenticated;
grant all on table public.hub_test_items, public.hub_eval_runs, public.hub_eval_results to service_role;
create policy hub_test_items_read on public.hub_test_items for select to authenticated using (internal.can('assistant', 'view') and (not is_test or internal.is_admin()));
create policy hub_eval_runs_read on public.hub_eval_runs for select to authenticated using ((internal.can('assistant', 'view') or internal.can('knowledge', 'publish')) and (not is_test or internal.is_admin()));
create policy hub_eval_results_read on public.hub_eval_results for select to authenticated
  using (exists (select 1 from public.hub_eval_runs r where r.id = run_id and (internal.can('assistant', 'view') or internal.can('knowledge', 'publish')) and (not r.is_test or internal.is_admin())));

-- the seed (tests/hub-bank/seed.jsonl, 102 questions; the header's global forbidden list lives in
-- _shared/hub/bank-rules.generated.json)
insert into public.hub_test_items (key, unit_key, language, messages, context, expect, note, sort, added_from)
select e ->> 'id', e ->> 'unit', e ->> 'language', e -> 'messages', coalesce(e -> 'context', '{}'::jsonb), e -> 'expect', e ->> 'note', o::int, 'seed'
  from jsonb_array_elements($seed_bank$/*@BANK_JSON@*/$seed_bank$::jsonb) with ordinality as x(e, o)
on conflict (key) do nothing;

-- ───────────────────────────────────────────── 2. what a run judges ─────────────────────────────────────────────

-- the live configuration of these units: the published cards and FAQ, the units' published persona and skills, the models
create function internal.hub_live_hash(p_units text[]) returns text
language sql stable security definer set search_path = '' as $$
  select md5(concat_ws('|',
    (select coalesce(string_agg(k.key || ':' || k.live::text, ',' order by k.key), '') from public.hub_knowledge_cards k where k.status = 'published' and k.live is not null and not k.is_test),
    (select coalesce(string_agg(f.key || ':' || f.live::text, ',' order by f.key), '') from public.faq_items f where f.live is not null and not f.is_test),
    (select coalesce(string_agg(u.key || ':' || coalesce(u.persona_live::text, '') || ':' || array_to_string(u.skills, ','), ',' order by u.key), '') from public.hub_units u where u.key = any (p_units)),
    (select coalesce(s.value::text, '') from public.settings s where s.key = 'hub_models'),
    (select coalesce(string_agg(t.key || ':' || t.status || ':' || coalesce(t.parent_key, ''), ',' order by t.key), '') from public.hub_topics t where not t.is_test)))
$$;

-- the cards «نشر» would publish now (drafts and edits, never archived) and their hash
create function internal.hub_pending_cards() returns uuid[]
language sql stable security definer set search_path = '' as $$
  select coalesce(array_agg(c.id order by c.sort, c.key), '{}') from public.hub_knowledge_cards c where internal.hub_card_pending(c) and (not c.is_test or internal.is_admin())
$$;
create function internal.hub_cards_hash(p_ids uuid[]) returns text
language sql stable security definer set search_path = '' as $$
  select md5(coalesce(string_agg(c.id::text || ':' || internal.hub_card_snapshot(c)::text, ',' order by c.id), '')) from public.hub_knowledge_cards c where c.id = any (p_ids)
$$;

-- the units a gate judges: the active units that hold bank items
create function internal.hub_eval_units() returns text[]
language sql stable security definer set search_path = '' as $$
  select coalesce(array_agg(u.key order by u.sort, u.key), '{}') from public.hub_units u
   where u.status = 'active' and not u.is_test and exists (select 1 from public.hub_test_items i where i.unit_key = u.key and i.status = 'active')
$$;

-- the items the engine runs (the router's own items — the «إلغاء» question, an opt-out — are not engine turns); an item
-- that needs a published card's text ({card:<id>}) that is not there is left out
create function internal.hub_eval_items(p_units text[]) returns setof public.hub_test_items
language sql stable security definer set search_path = '' as $$
  select i.* from public.hub_test_items i
   where i.status = 'active' and not i.is_test and i.unit_key = any (p_units)
     and coalesce(i.expect ->> 'action', '') not in ('cancel_word_question', 'opt_out')
     and not exists (select 1 from regexp_matches(i.expect::text, '\{card:(k-[a-z0-9-]+)\}', 'g') m
                      where not exists (select 1 from public.hub_knowledge_cards k where k.key = m[1] and k.status = 'published' and k.live is not null))
   order by i.sort, i.key
$$;

-- what one item costs (USD): the average of the last finished results, else the recorded measure of H5 (both models)
create function internal.hub_eval_item_cost() returns numeric
language sql stable security definer set search_path = '' as $$
  select coalesce((select avg(x.cost_usd) from (select r.cost_usd from public.hub_eval_results r where r.status in ('pass', 'fail') and r.cost_usd > 0
                                                   order by r.finished_at desc limit 200) x), 0.0066)::numeric(12, 6)
$$;

-- the items of a gate: knowledge — those whose last understood topics (from the latest live result) meet the candidate
-- cards' topics (the cards' old topics, parents and children included), those that expect a candidate card, and those
-- never run; persona — every item of the unit
create function internal.hub_gate_items(p_kind text, p_units text[], p_cards uuid[]) returns uuid[]
language plpgsql stable security definer set search_path = '' as $$
declare
  v_topics text[];
  v_keys text[];
begin
  if p_kind = 'persona' then return array(select i.id from internal.hub_eval_items(p_units) i); end if;
  v_topics := array(select distinct k from public.hub_knowledge_cards c,
                      lateral (select unnest(c.topic_keys) union select jsonb_array_elements_text(coalesce(c.live -> 'topic_keys', '[]'::jsonb))) t(k) where c.id = any (p_cards));
  v_topics := v_topics || array(select t.parent_key from public.hub_topics t where t.key = any (v_topics) and t.parent_key is not null)
                       || array(select t.key from public.hub_topics t where t.parent_key = any (v_topics));
  v_keys := array(select c.key from public.hub_knowledge_cards c where c.id = any (p_cards));
  return array(
    select i.id from internal.hub_eval_items(p_units) i
     where coalesce(i.expect -> 'cards', '[]'::jsonb) ?| v_keys
        or not exists (select 1 from public.hub_eval_results r join public.hub_eval_runs u on u.id = r.run_id
                        where r.item_id = i.id and r.config = 'live' and r.status in ('pass', 'fail') and not u.is_test)
        or exists (select 1 from (select r.outcome from public.hub_eval_results r join public.hub_eval_runs u on u.id = r.run_id
                                   where r.item_id = i.id and r.config = 'live' and r.status in ('pass', 'fail') and not u.is_test
                                   order by r.finished_at desc limit 1) z
                    where coalesce(z.outcome -> 'topics', '[]'::jsonb) ?| v_topics));
end;
$$;

-- the latest finished live result of each item on THIS live configuration and engine (a gate reuses it instead of
-- running the live side again — within 7 days)
create function internal.hub_eval_reusable(p_item uuid, p_hash text, p_engine text) returns public.hub_eval_results
language sql stable security definer set search_path = '' as $$
  select r.* from public.hub_eval_results r join public.hub_eval_runs u on u.id = r.run_id
   where r.item_id = p_item and r.config = 'live' and r.status in ('pass', 'fail') and u.live_hash = p_hash and u.engine is not distinct from p_engine
     and not u.is_test and r.finished_at > now() - interval '7 days'
   order by r.finished_at desc limit 1
$$;

-- what a run would do and cost (as the user): {kind, units, items, live_items, candidate_items, est_cost_usd, budget,
-- would_pass_cap, nothing}. manual / baseline: assistant: edit; knowledge: knowledge: publish; persona: assistant: edit
-- in the unit's branch.
create function public.hub_eval_plan(p_kind text, p_unit text default null, p_engine text default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_units text[];
  v_cards uuid[];
  v_items uuid[];
  v_hash text;
  v_live integer := 0;
  v_cand integer := 0;
  v_cost numeric := internal.hub_eval_item_cost();
  v_est numeric;
  b jsonb := internal.hub_budget_state();
  u public.hub_units;
  i uuid;
begin
  if p_kind not in ('manual', 'baseline', 'knowledge', 'persona') then raise exception 'hub_eval_kind' using errcode = '22023'; end if;
  if p_kind = 'knowledge' then
    if not internal.can('knowledge', 'publish') then raise exception 'not allowed' using errcode = '42501'; end if;
  elsif not internal.can('assistant', 'edit') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_unit is not null then
    select * into u from public.hub_units where key = p_unit;
    if u.id is null then raise exception 'hub_unit' using errcode = '22023'; end if;
    if not internal.can_branch(u.branch_slug) then raise exception 'not allowed' using errcode = '42501'; end if;
  elsif p_kind = 'persona' then
    raise exception 'hub_unit' using errcode = '22023';
  end if;
  v_units := case when p_unit is not null then array[p_unit] else internal.hub_eval_units() end;
  if p_kind = 'knowledge' and p_unit is null then v_units := internal.hub_eval_units(); end if;
  v_hash := internal.hub_live_hash(v_units);
  if p_kind in ('manual', 'baseline') then
    v_items := array(select x.id from internal.hub_eval_items(v_units) x);
    v_live := cardinality(v_items);
  else
    v_cards := case when p_kind = 'knowledge' then internal.hub_pending_cards() else '{}' end;
    if p_kind = 'knowledge' and cardinality(v_cards) = 0 then
      return jsonb_build_object('kind', p_kind, 'units', to_jsonb(v_units), 'items', 0, 'nothing', true, 'est_cost_usd', 0, 'budget', b, 'would_pass_cap', false);
    end if;
    if p_kind = 'persona' and u.persona is not distinct from u.persona_live then
      return jsonb_build_object('kind', p_kind, 'units', to_jsonb(v_units), 'items', 0, 'nothing', true, 'est_cost_usd', 0, 'budget', b, 'would_pass_cap', false);
    end if;
    v_items := internal.hub_gate_items(p_kind, v_units, v_cards);
    v_cand := cardinality(v_items);
    foreach i in array v_items loop
      if (internal.hub_eval_reusable(i, v_hash, p_engine)).id is null then v_live := v_live + 1; end if;
    end loop;
  end if;
  -- a retry for an item that fails is counted in (15 %)
  v_est := round((v_live + v_cand) * v_cost * 1.15, 6);
  return jsonb_build_object('kind', p_kind, 'units', to_jsonb(v_units), 'items', cardinality(v_items), 'live_items', v_live, 'candidate_items', v_cand,
    'cards', cardinality(coalesce(v_cards, '{}')), 'item_cost_usd', v_cost, 'est_cost_usd', v_est, 'nothing', false, 'budget', b,
    'would_pass_cap', coalesce((b ->> 'capped')::boolean, false)
                      or ((b ->> 'daily_budget') is not null and (b ->> 'daily_spent')::numeric + v_est > (b ->> 'daily_budget')::numeric)
                      or ((b ->> 'monthly_budget') is not null and (b ->> 'monthly_spent')::numeric + v_est > (b ->> 'monthly_budget')::numeric),
    'busy', exists (select 1 from public.hub_eval_runs r where r.status in ('queued', 'running') and not r.is_test));
end;
$$;

-- the run starts (as the user, through hub-admin eval_run): refused past the cap, one at a time. A gate whose candidate
-- touches no item is finished at once with a pass (nothing it could change).
create function public.hub_eval_start(p_kind text, p_unit text default null, p_engine text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  p jsonb := public.hub_eval_plan(p_kind, p_unit, p_engine);
  v_units text[] := array(select jsonb_array_elements_text(p -> 'units'));
  v_hash text := internal.hub_live_hash(array(select jsonb_array_elements_text(p -> 'units')));
  v_run uuid;
  v_cards uuid[];
  v_items uuid[];
  u public.hub_units;
  i uuid;
  r public.hub_eval_results;
  v_cand jsonb;
begin
  if coalesce((p ->> 'nothing')::boolean, false) then raise exception 'hub_eval_nothing' using errcode = 'P0001'; end if;
  if coalesce((p ->> 'busy')::boolean, false) then raise exception 'hub_eval_busy' using errcode = 'P0001'; end if;
  if coalesce((p ->> 'would_pass_cap')::boolean, false) then raise exception 'hub_eval_cap' using errcode = 'P0001', detail = (p ->> 'est_cost_usd'); end if;
  if p_kind = 'knowledge' then
    v_cards := internal.hub_pending_cards();
    v_cand := jsonb_build_object('cards', to_jsonb(v_cards), 'cards_hash', internal.hub_cards_hash(v_cards));
  elsif p_kind = 'persona' then
    select * into u from public.hub_units where key = p_unit;
    v_cand := jsonb_build_object('unit', u.key, 'persona', u.persona, 'persona_hash', md5(u.persona::text));
  end if;
  insert into public.hub_eval_runs (trigger, units, candidate, live_hash, engine, est_cost_usd, requested_by, status, started_at)
  values (p_kind, v_units, v_cand, v_hash, nullif(p_engine, ''), coalesce((p ->> 'est_cost_usd')::numeric, 0), auth.uid(), 'queued', now())
  returning id into v_run;
  if p_kind in ('manual', 'baseline') then
    insert into public.hub_eval_results (run_id, item_id, config) select v_run, x.id, 'live' from internal.hub_eval_items(v_units) x;
  else
    v_items := internal.hub_gate_items(p_kind, v_units, v_cards);
    foreach i in array v_items loop
      insert into public.hub_eval_results (run_id, item_id, config) values (v_run, i, 'candidate');
      r := internal.hub_eval_reusable(i, v_hash, p_engine);
      if r.id is null then
        insert into public.hub_eval_results (run_id, item_id, config) values (v_run, i, 'live');
      else
        -- the live side of this configuration was judged already: its result is reused (no new model call)
        insert into public.hub_eval_results (run_id, item_id, config, attempt, status, reasons, replies, outcome, cost_usd, finished_at)
        values (v_run, i, 'live', r.attempt, r.status, r.reasons, r.replies, r.outcome, 0, r.finished_at);
      end if;
    end loop;
  end if;
  update public.hub_eval_runs set items_total = (select count(distinct x.item_id) from public.hub_eval_results x where x.run_id = v_run) where id = v_run;
  perform internal.hub_eval_settle(v_run);
  perform internal.hub_agent_post('sweep');
  return jsonb_build_object('ok', true, 'run_id', v_run, 'plan', p);
end;
$$;

-- the verdict once nothing is pending (spec §4.8): manual / baseline — blocked = failing items that are not a known gap;
-- a gate — blocked = items that pass live and fail on the candidate; known gaps = failing on both (or flagged)
create function internal.hub_eval_settle(p_run uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  run public.hub_eval_runs;
  v_open integer;
  v_blocked jsonb;
  v_gaps jsonb;
begin
  select * into run from public.hub_eval_runs where id = p_run for update;
  if run.id is null or run.status not in ('queued', 'running') then return; end if;
  select count(*) into v_open from public.hub_eval_results r where r.run_id = run.id and r.status in ('pending', 'running');
  update public.hub_eval_runs
     set items_done = (select count(distinct x.item_id) from public.hub_eval_results x where x.run_id = run.id
                        and not exists (select 1 from public.hub_eval_results y where y.run_id = run.id and y.item_id = x.item_id and y.status in ('pending', 'running'))),
         passed = (select count(*) from public.hub_eval_results x where x.run_id = run.id and x.status = 'pass' and x.config = case when run.trigger in ('manual', 'baseline') then 'live' else 'candidate' end),
         failed = (select count(*) from public.hub_eval_results x where x.run_id = run.id and x.status = 'fail' and x.config = case when run.trigger in ('manual', 'baseline') then 'live' else 'candidate' end),
         errors = (select count(*) from public.hub_eval_results x where x.run_id = run.id and x.status = 'error'),
         cost_usd = (select coalesce(sum(x.cost_usd), 0) from public.hub_eval_results x where x.run_id = run.id),
         status = case when v_open > 0 and run.status = 'queued' and exists (select 1 from public.hub_eval_results x where x.run_id = run.id and x.status <> 'pending') then 'running' else status end
   where id = run.id;
  if v_open > 0 then return; end if;
  -- a gate: a candidate that failed while its live side passed is tried once more before it blocks
  if run.trigger in ('knowledge', 'persona') then
    update public.hub_eval_results c set status = 'pending', attempt = c.attempt + 1, finished_at = null
     where c.run_id = run.id and c.config = 'candidate' and c.status in ('fail', 'error') and c.attempt = 1
       and exists (select 1 from public.hub_eval_results l where l.run_id = run.id and l.item_id = c.item_id and l.config = 'live' and l.status = 'pass');
    if found then return; end if;
  end if;
  if run.trigger in ('manual', 'baseline') then
    select coalesce(jsonb_agg(jsonb_build_object('key', i.key, 'unit', i.unit_key) order by i.sort, i.key) filter (where i.known_gap_at is null), '[]'::jsonb),
           coalesce(jsonb_agg(jsonb_build_object('key', i.key, 'unit', i.unit_key) order by i.sort, i.key) filter (where i.known_gap_at is not null), '[]'::jsonb)
      into v_blocked, v_gaps
      from public.hub_eval_results r join public.hub_test_items i on i.id = r.item_id where r.run_id = run.id and r.status in ('fail', 'error');
  else
    select coalesce(jsonb_agg(jsonb_build_object('key', i.key, 'unit', i.unit_key) order by i.sort, i.key) filter (where l.status = 'pass'), '[]'::jsonb),
           coalesce(jsonb_agg(jsonb_build_object('key', i.key, 'unit', i.unit_key) order by i.sort, i.key) filter (where l.status is distinct from 'pass'), '[]'::jsonb)
      into v_blocked, v_gaps
      from public.hub_eval_results c join public.hub_test_items i on i.id = c.item_id
      left join public.hub_eval_results l on l.run_id = c.run_id and l.item_id = c.item_id and l.config = 'live'
     where c.run_id = run.id and c.config = 'candidate' and c.status in ('fail', 'error');
  end if;
  update public.hub_eval_runs set status = 'done', finished_at = now(), blocked_items = v_blocked, known_gaps = v_gaps,
         verdict = case when jsonb_array_length(v_blocked) > 0 then 'blocked' else 'pass' end
   where id = run.id;
end;
$$;

-- a run stops (the budget cap, a cancel): what is pending is skipped; the verdict is «failed»
create function internal.hub_eval_stop(p_run uuid, p_reason text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  update public.hub_eval_results set status = 'skipped', finished_at = now() where run_id = p_run and status in ('pending', 'running');
  update public.hub_eval_runs set status = case when p_reason = 'cancelled' then 'cancelled' else 'failed' end, verdict = 'failed', stop_reason = p_reason, finished_at = now(),
         cost_usd = (select coalesce(sum(x.cost_usd), 0) from public.hub_eval_results x where x.run_id = p_run)
   where id = p_run and status in ('queued', 'running');
end;
$$;

-- «إيقاف التشغيل» (assistant: edit, or the knowledge publisher who started it)
create function public.hub_eval_cancel(p_run uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare run public.hub_eval_runs;
begin
  select * into run from public.hub_eval_runs where id = p_run for update;
  if run.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if not (internal.can('assistant', 'edit') or (run.trigger = 'knowledge' and internal.can('knowledge', 'publish'))) then raise exception 'not allowed' using errcode = '42501'; end if;
  if run.status not in ('queued', 'running') then return jsonb_build_object('ok', true, 'changed', false); end if;
  perform internal.hub_eval_stop(run.id, 'cancelled');
  return jsonb_build_object('ok', true, 'changed', true);
end;
$$;

-- the next items to run (service role, hub-agent): pending results of the active run, claimed; a result stuck for 4
-- minutes is tried again (at most 3 attempts). The budget is read first: at the cap the run stops.
create function public.hub_eval_claim(p_limit integer default 6) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  run public.hub_eval_runs;
  b jsonb := internal.hub_budget_state();
  v_out jsonb;
  v_ids uuid[];
begin
  select * into run from public.hub_eval_runs where status in ('queued', 'running') order by created_at limit 1 for update skip locked;
  if run.id is null then return jsonb_build_object('items', '[]'::jsonb); end if;
  if coalesce((b ->> 'capped')::boolean, false) or coalesce((b ->> 'unset')::boolean, false) then
    perform internal.hub_eval_stop(run.id, 'budget_cap');
    return jsonb_build_object('items', '[]'::jsonb, 'stopped', 'budget_cap');
  end if;
  update public.hub_eval_results set status = case when attempt >= 3 then 'error' else 'pending' end, attempt = least(attempt + 1, 3),
         reasons = case when attempt >= 3 then array['stuck'] else reasons end, finished_at = case when attempt >= 3 then now() end
   where run_id = run.id and status = 'running' and claimed_at < now() - interval '4 minutes';
  update public.hub_eval_runs set status = 'running' where id = run.id and status = 'queued';
  with picked as (
    select r.id from public.hub_eval_results r where r.run_id = run.id and r.status = 'pending'
     order by case r.config when 'live' then 0 else 1 end, r.created_at limit least(greatest(coalesce(p_limit, 6), 1), 20) for update skip locked),
  upd as (update public.hub_eval_results r set status = 'running', claimed_at = now() from picked where r.id = picked.id returning r.id)
  select coalesce(array_agg(upd.id), '{}') into v_ids from upd;
  select coalesce(jsonb_agg(jsonb_build_object(
           'result_id', r.id, 'run_id', r.run_id, 'config', r.config, 'attempt', r.attempt, 'trigger', run.trigger,
           'item', jsonb_build_object('id', i.id, 'key', i.key, 'unit_key', i.unit_key, 'language', i.language, 'messages', i.messages, 'context', i.context, 'expect', i.expect),
           'cards', case when r.config = 'candidate' then run.candidate -> 'cards' end,
           'persona', case when r.config = 'candidate' and run.candidate ->> 'unit' = i.unit_key then run.candidate -> 'persona' end) order by r.created_at), '[]'::jsonb)
    into v_out
    from public.hub_eval_results r join public.hub_test_items i on i.id = r.item_id
   where r.id = any (v_ids);
  return jsonb_build_object('items', v_out, 'run_id', run.id);
end;
$$;

-- the context of one item (service role): what hub_turn_claim hands the engine, for a test question of this unit —
-- the unit (its published persona and skills), the topics, the licences, the settings, the shared forbidden list, the fees
create function public.hub_eval_context(p_unit text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare u public.hub_units;
begin
  select * into u from public.hub_units where key = p_unit;
  if u.id is null then raise exception 'hub_unit' using errcode = '22023'; end if;
  return jsonb_build_object(
    'unit', jsonb_build_object('id', u.id, 'key', u.key, 'kind', u.kind, 'branch', u.branch_slug, 'name_ar', u.name_ar, 'name_en', u.name_en,
      'mode', 'test', 'skills', to_jsonb(u.skills), 'persona', u.persona_live,
      'venue', (select jsonb_build_object('name_ar', v.name_ar, 'name_en', v.name_en, 'menu', v.menu) from public.dining_venues v where v.id = u.dining_venue_id)),
    'channel', (select jsonb_build_object('address', ch.address, 'sending_enabled', false) from public.hub_channels ch where ch.unit_id = u.id order by ch.created_at limit 1),
    'licences', (select coalesce(jsonb_object_agg(l.topic_key, l.mode), '{}') from public.hub_licences l where l.unit_id = u.id),
    'topics', (select coalesce(jsonb_agg(jsonb_build_object('key', x.key, 'label_en', x.label_en, 'label_ar', x.label_ar, 'parent_key', x.parent_key, 'always_handoff', x.always_handoff) order by x.sort, x.key), '[]')
                 from public.hub_topics x where x.status = 'active' and not x.is_test),
    'settings', jsonb_build_object(
      'confidence_floor', coalesce((select (s.value #>> '{}')::numeric from public.settings s where s.key = 'hub_confidence_floor'), 0.7),
      'cards_per_turn', internal.hub_setting_int('hub_cards_per_turn', 5), 'reply_max_chars', internal.hub_setting_int('hub_reply_max_chars', 600),
      'failed_max', internal.hub_setting_int('hub_failed_understanding_max', 2), 'group_min_rooms', internal.hub_setting_int('hub_group_min_rooms', 5),
      'models', (select s.value from public.settings s where s.key = 'hub_models'), 'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'),
      'show_prices', coalesce((select (s.value ->> u.branch_slug)::boolean from public.settings s where s.key = 'show_prices'), false)),
    'forbidden', to_jsonb(internal.hub_forbidden_terms()),
    'fees', jsonb_build_object('breakfast', (select s.value from public.settings s where s.key = 'breakfast'),
                               'extra_bed_per_night', (select (s.value #>> '{}')::numeric from public.settings s where s.key = 'extra_bed_per_night')),
    'cards', (select coalesce(jsonb_object_agg(k.key, jsonb_build_object('ar', k.live ->> 'text_ar', 'en', k.live ->> 'text_en')), '{}')
                from public.hub_knowledge_cards k where k.status = 'published' and k.live is not null and k.key like 'k-wifi-password-%'),
    'budget', internal.hub_budget_state(),
    'today', internal.riyadh_today());
end;
$$;

/*@KNOWLEDGE_FOR_EVAL@*/

-- one item's outcome (service role): its models into the budget (source test_lab); a candidate that fails while its
-- live side passed — and any failure of a full run — is tried once more before it counts; then the run's verdict
create function public.hub_eval_finish(p_result uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  r public.hub_eval_results;
  run public.hub_eval_runs;
  u public.hub_units;
  m jsonb;
  v_cost numeric := 0;
  v_status text := case when p ->> 'status' in ('pass', 'fail', 'error') then p ->> 'status' else 'error' end;
  v_retry boolean := false;
begin
  select * into r from public.hub_eval_results where id = p_result for update;
  if r.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if r.status <> 'running' then return jsonb_build_object('ok', false, 'reason', 'not_running'); end if;
  select * into run from public.hub_eval_runs where id = r.run_id;
  select u2.* into u from public.hub_units u2 join public.hub_test_items i on i.unit_key = u2.key where i.id = r.item_id;
  for m in select * from jsonb_array_elements(coalesce(p -> 'models', '[]'::jsonb)) loop
    if m ->> 'layer' in ('understand', 'tag', 'compose') and coalesce((m ->> 'input_tokens')::bigint, 0) + coalesce((m ->> 'output_tokens')::bigint, 0) > 0 then
      v_cost := v_cost + internal.hub_usage_add(u.id, m ->> 'layer', 'test_lab', m ->> 'model', (m ->> 'input_tokens')::bigint, (m ->> 'output_tokens')::bigint, run.is_test);
    end if;
  end loop;
  -- a full run tries a failing item once more; a gate does it in internal.hub_eval_settle, once both sides are in
  v_retry := v_status in ('fail', 'error') and r.attempt = 1 and run.trigger in ('manual', 'baseline');
  update public.hub_eval_results
     set status = case when v_retry then 'pending' else v_status end, attempt = case when v_retry then attempt + 1 else attempt end,
         reasons = array(select x from jsonb_array_elements_text(coalesce(p -> 'reasons', '[]'::jsonb)) x where x ~ '^[a-z_:0-9-]{2,80}$' limit 30),
         replies = coalesce(p -> 'replies', '[]'::jsonb), outcome = p -> 'outcome', cost_usd = cost_usd + v_cost,
         finished_at = case when v_retry then null else now() end
   where id = r.id;
  perform internal.hub_eval_settle(r.run_id);
  return jsonb_build_object('ok', true, 'retry', v_retry, 'cost_usd', v_cost);
end;
$$;

-- reads for «مختبر الاختبار» (assistant: view; a knowledge publisher reads the runs of its gates)
create function public.hub_eval_runs_list(p_limit integer default 20) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not (internal.can('assistant', 'view') or internal.can('knowledge', 'publish')) then raise exception 'not allowed' using errcode = '42501'; end if;
  return jsonb_build_object(
    'runs', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'trigger', r.trigger, 'units', to_jsonb(r.units), 'status', r.status, 'verdict', r.verdict,
                        'items_total', r.items_total, 'items_done', r.items_done, 'passed', r.passed, 'failed', r.failed, 'errors', r.errors,
                        'est_cost_usd', r.est_cost_usd, 'cost_usd', r.cost_usd, 'blocked', r.blocked_items, 'known_gaps', r.known_gaps, 'stop_reason', r.stop_reason,
                        'requested_by_name', (select s.full_name from public.staff s where s.user_id = r.requested_by),
                        'started_at', r.started_at, 'finished_at', r.finished_at, 'created_at', r.created_at) order by r.created_at desc)
                       from (select * from public.hub_eval_runs x where not x.is_test or internal.is_admin() order by x.created_at desc limit least(greatest(coalesce(p_limit, 20), 1), 100)) r), '[]'::jsonb),
    'item_cost_usd', internal.hub_eval_item_cost(),
    'budget', internal.hub_budget_state());
end;
$$;

create function public.hub_eval_run(p_run uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare run public.hub_eval_runs;
begin
  if not (internal.can('assistant', 'view') or internal.can('knowledge', 'publish')) then raise exception 'not allowed' using errcode = '42501'; end if;
  select * into run from public.hub_eval_runs where id = p_run;
  if run.id is null or (run.is_test and not internal.is_admin()) then raise exception 'not_found' using errcode = '22023'; end if;
  return jsonb_build_object(
    'run', jsonb_build_object('id', run.id, 'trigger', run.trigger, 'units', to_jsonb(run.units), 'status', run.status, 'verdict', run.verdict,
      'items_total', run.items_total, 'items_done', run.items_done, 'passed', run.passed, 'failed', run.failed, 'errors', run.errors,
      'est_cost_usd', run.est_cost_usd, 'cost_usd', run.cost_usd, 'blocked', run.blocked_items, 'known_gaps', run.known_gaps, 'stop_reason', run.stop_reason,
      'candidate_cards', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'key', c.key, 'title_ar', c.title_ar)), '[]'::jsonb)
                            from public.hub_knowledge_cards c where c.id = any (array(select jsonb_array_elements_text(coalesce(run.candidate -> 'cards', '[]'::jsonb))::uuid))),
      'persona_unit', run.candidate ->> 'unit', 'started_at', run.started_at, 'finished_at', run.finished_at),
    'results', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'item_key', i.key, 'unit', i.unit_key, 'language', i.language, 'messages', i.messages,
                           'expect', i.expect, 'known_gap', i.known_gap_at is not null, 'config', r.config, 'attempt', r.attempt, 'status', r.status,
                           'reasons', to_jsonb(r.reasons), 'replies', r.replies, 'outcome', r.outcome, 'cost_usd', r.cost_usd) order by i.sort, i.key, r.config)
                          from public.hub_eval_results r join public.hub_test_items i on i.id = r.item_id where r.run_id = run.id), '[]'::jsonb));
end;
$$;

-- the bank (assistant: view) with each item's last live result
create function public.hub_test_items_list() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not internal.can('assistant', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  return jsonb_build_object('items', coalesce((select jsonb_agg(jsonb_build_object(
      'id', i.id, 'key', i.key, 'unit_key', i.unit_key, 'language', i.language, 'messages', i.messages, 'context', i.context, 'expect', i.expect, 'note', i.note,
      'tags', to_jsonb(i.tags), 'status', i.status, 'added_from', i.added_from, 'known_gap', i.known_gap_at is not null, 'known_gap_reason', i.known_gap_reason,
      'router_only', coalesce(i.expect ->> 'action', '') in ('cancel_word_question', 'opt_out'),
      'last', (select jsonb_build_object('status', r.status, 'reasons', to_jsonb(r.reasons), 'at', r.finished_at) from public.hub_eval_results r join public.hub_eval_runs u on u.id = r.run_id
                where r.item_id = i.id and r.config = 'live' and r.status in ('pass', 'fail', 'error') and not u.is_test order by r.finished_at desc limit 1))
      order by i.sort, i.key) from public.hub_test_items i where not i.is_test or internal.is_admin()), '[]'::jsonb),
    'can_edit', internal.can('assistant', 'edit'));
end;
$$;

-- an item (assistant: edit): new from «مختبر الاختبار» or «حفظ كسؤال اختبار» in «المحاكي», or an edit
create function public.hub_test_item_save(p_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_id uuid := p_id;
  v_key text;
  v_expect jsonb := coalesce(p -> 'expect', '{}'::jsonb);
  v_msgs jsonb := coalesce(p -> 'messages', '[]'::jsonb);
  v_from text := coalesce(p ->> 'added_from', 'staff');
  v_batch uuid;
begin
  if not internal.can('assistant', 'edit') then raise exception 'not allowed' using errcode = '42501'; end if;
  if not exists (select 1 from public.hub_units u where u.key = p ->> 'unit_key' and internal.can_branch(u.branch_slug)) then raise exception 'hub_unit' using errcode = '22023'; end if;
  if coalesce(p ->> 'language', '') not in ('ar', 'en') then raise exception 'hub_test_language' using errcode = '22023'; end if;
  if jsonb_typeof(v_msgs) <> 'array' or jsonb_array_length(v_msgs) not between 1 and 10
     or exists (select 1 from jsonb_array_elements(v_msgs) x where jsonb_typeof(x) <> 'string' or char_length(btrim(x #>> '{}')) not between 1 and 600) then
    raise exception 'hub_test_messages' using errcode = '22023';
  end if;
  if coalesce(v_expect ->> 'action', '') not in ('answer', 'ask', 'quote', 'handoff', 'booking_status', 'refuse', 'third_language', 'greeting', 'send_summary') then
    raise exception 'hub_test_action' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_each(v_expect) e where e.key not in ('action', 'cards', 'faq', 'must_include', 'must_not_include', 'state')) then raise exception 'hub_test_expect' using errcode = '22023'; end if;
  if exists (select 1 from jsonb_each(v_expect) e where e.key in ('cards', 'faq', 'must_include', 'must_not_include')
               and (jsonb_typeof(e.value) <> 'array' or jsonb_array_length(e.value) > 10
                    or exists (select 1 from jsonb_array_elements(e.value) y where jsonb_typeof(y) <> 'string' or char_length(y #>> '{}') not between 1 and 120))) then
    raise exception 'hub_test_expect' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements_text(coalesce(v_expect -> 'cards', '[]'::jsonb)) k where not exists (select 1 from public.hub_knowledge_cards c where c.key = k)) then
    raise exception 'hub_test_card' using errcode = '22023';
  end if;
  if v_expect ? 'state' and coalesce(v_expect ->> 'state', '') not in ('new', 'inquiry', 'collecting', 'quoted', 'awaiting_confirmation', 'booked', 'human', 'closed') then
    raise exception 'hub_test_expect' using errcode = '22023';
  end if;
  if v_from not in ('staff', 'simulator', 'queue') then v_from := 'staff'; end if;
  v_batch := internal.begin_batch();
  if v_id is null then
    v_key := 's-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 8);
    insert into public.hub_test_items (key, unit_key, language, messages, expect, note, tags, added_from, sort, created_by)
    values (v_key, p ->> 'unit_key', p ->> 'language', v_msgs, v_expect, nullif(left(btrim(coalesce(p ->> 'note', '')), 500), ''),
            array(select left(x, 40) from jsonb_array_elements_text(coalesce(p -> 'tags', '[]'::jsonb)) x limit 10), v_from,
            coalesce((select max(x.sort) + 1 from public.hub_test_items x), 0), auth.uid())
    returning id into v_id;
  else
    update public.hub_test_items set unit_key = p ->> 'unit_key', language = p ->> 'language', messages = v_msgs, expect = v_expect,
           note = nullif(left(btrim(coalesce(p ->> 'note', '')), 500), ''), tags = array(select left(x, 40) from jsonb_array_elements_text(coalesce(p -> 'tags', '[]'::jsonb)) x limit 10)
     where id = v_id and added_from <> 'seed';
    if not found then raise exception 'hub_test_seed' using errcode = '22023', hint = 'a seed question is retired, not edited'; end if;
  end if;
  return jsonb_build_object('ok', true, 'id', v_id, 'batch_id', v_batch);
end;
$$;

-- «إيقاف السؤال» / «إعادة تفعيله» (assistant: edit) — «تراجع» = the other
create function public.hub_test_item_retire(p_id uuid, p_retired boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_batch uuid;
begin
  if not internal.can('assistant', 'edit') then raise exception 'not allowed' using errcode = '42501'; end if;
  v_batch := internal.begin_batch();
  update public.hub_test_items set status = case when p_retired then 'retired' else 'active' end where id = p_id and status = case when p_retired then 'active' else 'retired' end;
  if not found then return jsonb_build_object('ok', true, 'changed', false); end if;
  return jsonb_build_object('ok', true, 'changed', true, 'batch_id', v_batch);
end;
$$;

-- «فجوة معروفة» (assistant: edit on every branch): a failure that is known — it never blocks the shadow gate; with a reason
create function public.hub_test_item_gap(p_id uuid, p_gap boolean, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_batch uuid;
begin
  if not internal.can('assistant', 'edit') or not internal.all_branches() then raise exception 'not allowed' using errcode = '42501'; end if;
  if p_gap and char_length(btrim(coalesce(p_reason, ''))) not between 3 and 300 then raise exception 'hub_reason' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  update public.hub_test_items set known_gap_at = case when p_gap then now() end, known_gap_by = case when p_gap then auth.uid() end,
         known_gap_reason = case when p_gap then btrim(p_reason) end
   where id = p_id and (known_gap_at is not null) <> p_gap;
  if not found then return jsonb_build_object('ok', true, 'changed', false); end if;
  return jsonb_build_object('ok', true, 'changed', true, 'batch_id', v_batch);
end;
$$;

-- ───────────────────────────────────────────── 3. the gates ─────────────────────────────────────────────

-- the unit's latest full run (manual or baseline, finished): what it found for this unit's items
create function internal.hub_unit_lab(u public.hub_units) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce((
    select jsonb_build_object('run_id', run.id, 'finished_at', run.finished_at, 'trigger', run.trigger,
      'items', (select count(*) from public.hub_eval_results r join public.hub_test_items i on i.id = r.item_id where r.run_id = run.id and i.unit_key = u.key),
      'passed', (select count(*) from public.hub_eval_results r join public.hub_test_items i on i.id = r.item_id where r.run_id = run.id and i.unit_key = u.key and r.status = 'pass'),
      'blocking', (select coalesce(jsonb_agg(i.key order by i.sort, i.key), '[]'::jsonb) from public.hub_eval_results r join public.hub_test_items i on i.id = r.item_id
                    where r.run_id = run.id and i.unit_key = u.key and r.status in ('fail', 'error') and i.known_gap_at is null and i.status = 'active'),
      'gaps', (select coalesce(jsonb_agg(i.key order by i.sort, i.key), '[]'::jsonb) from public.hub_eval_results r join public.hub_test_items i on i.id = r.item_id
                where r.run_id = run.id and i.unit_key = u.key and r.status in ('fail', 'error') and i.known_gap_at is not null))
      from public.hub_eval_runs run
     where run.status = 'done' and run.trigger in ('manual', 'baseline') and u.key = any (run.units) and not run.is_test
     order by run.finished_at desc limit 1), jsonb_build_object('run_id', null))
$$;

-- gate 5 of spec §1.8: the unit's latest full run exists and has no failing item other than a known gap
create or replace function internal.hub_test_lab_ready(u public.hub_units) returns boolean
language sql stable security definer set search_path = '' as $$
  select (internal.hub_unit_lab(u) ->> 'run_id') is not null and jsonb_array_length(coalesce(internal.hub_unit_lab(u) -> 'blocking', '[]'::jsonb)) = 0
     and coalesce((internal.hub_unit_lab(u) ->> 'items')::int, 0) > 0
$$;

-- the modes (Ahmed's H6 brief, 14 Nov 2026): «بموافقة الفريق» and «يرد تلقائيًا» are allowed with assistant: edit — the
-- gates of each mode still apply (the test lab for both); «المساعد يعمل» and the budgets stay the system admin's
create or replace function internal.hub_unit_mode_guard() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v jsonb;
begin
  if new.assistant_mode <> 'off' and (tg_op = 'INSERT' or new.assistant_mode is distinct from old.assistant_mode) then
    if new.status <> 'active' then
      raise exception 'unit_hidden' using errcode = 'P0001', hint = 'a hidden unit can never be switched on';
    end if;
    v := internal.hub_unit_gates_mode(new, new.assistant_mode);
    if jsonb_array_length(v) > 0 then
      raise exception 'hub_not_ready' using errcode = 'P0001', detail = v::text;
    end if;
    if not internal.can('assistant', 'edit') or not internal.can_branch(new.branch_slug) then
      raise exception 'not allowed' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

create or replace function public.hub_unit_mode_set(p_unit uuid, p_mode text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  u public.hub_units;
  v_batch uuid;
  v jsonb;
begin
  select * into u from public.hub_units where id = p_unit for update;
  if u.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if not internal.can('assistant', 'edit') or not internal.can_branch(u.branch_slug) then raise exception 'not allowed' using errcode = '42501'; end if;
  if p_mode is null or p_mode not in ('off', 'test', 'shadow', 'licensed') then raise exception 'hub_mode: off, test, shadow or licensed' using errcode = '22023'; end if;
  if p_mode <> 'off' then
    if u.status <> 'active' then raise exception 'unit_hidden' using errcode = 'P0001', hint = 'a hidden unit can never be switched on'; end if;
    v := internal.hub_unit_gates_mode(u, p_mode);
    if jsonb_array_length(v) > 0 then raise exception 'hub_not_ready' using errcode = 'P0001', detail = v::text; end if;
  end if;
  if p_mode = u.assistant_mode then raise exception 'nothing to change' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  update public.hub_units set assistant_mode = p_mode where id = p_unit;
  return jsonb_build_object('ok', true, 'batch_id', v_batch);
end;
$$;

-- the knowledge gate (spec §4.8; the H4 hook): a finished gate run on exactly these cards as they are now, verdict pass,
-- within 24 hours. {ok, gate, …} — never a pass without a run.
create or replace function internal.hub_knowledge_gate(p_cards uuid[]) returns jsonb
language sql stable set search_path = '' as $$
  select jsonb_build_object('ok', false, 'gate', 'eval_required', 'cards', cardinality(p_cards))
$$;
create function internal.hub_knowledge_gate_run(p_cards uuid[], p_run uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare run public.hub_eval_runs;
begin
  if p_run is null then return jsonb_build_object('ok', false, 'gate', 'eval_required', 'cards', cardinality(p_cards)); end if;
  select * into run from public.hub_eval_runs where id = p_run;
  if run.id is null or run.trigger <> 'knowledge' then return jsonb_build_object('ok', false, 'gate', 'eval_required'); end if;
  if run.status in ('queued', 'running') then return jsonb_build_object('ok', false, 'gate', 'eval_running', 'run_id', run.id); end if;
  if run.status <> 'done' or run.verdict is distinct from 'pass' then
    return jsonb_build_object('ok', false, 'gate', 'eval_blocked', 'run_id', run.id, 'blocked', run.blocked_items, 'verdict', run.verdict);
  end if;
  if run.finished_at < now() - interval '24 hours'
     or (select array_agg(x order by x) from unnest(p_cards) x) is distinct from (select array_agg(x::uuid order by x::uuid) from jsonb_array_elements_text(run.candidate -> 'cards') x)
     or internal.hub_cards_hash(p_cards) is distinct from run.candidate ->> 'cards_hash' then
    return jsonb_build_object('ok', false, 'gate', 'eval_stale', 'run_id', run.id);
  end if;
  return jsonb_build_object('ok', true, 'gate', 'eval', 'run_id', run.id, 'known_gaps', run.known_gaps);
end;
$$;

-- «نشر» (H4) with the gate's run: p_dry_run answers what blocks (problems first, then whether a run is needed)
drop function public.hub_knowledge_publish(boolean);
create function public.hub_knowledge_publish(p_dry_run boolean default false, p_eval_run uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_blocked jsonb;
  v_ids uuid[];
  v_gate jsonb;
  v_batch uuid;
begin
  if not internal.can('knowledge', 'publish') then raise exception 'not allowed' using errcode = '42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'key', c.key, 'title_ar', c.title_ar, 'missing', internal.hub_card_check(c) -> 'missing') order by c.sort), '[]'::jsonb)
    into v_blocked from public.hub_knowledge_cards c
   where (not c.is_test or internal.is_admin()) and internal.hub_card_pending(c) and jsonb_array_length(internal.hub_card_check(c) -> 'missing') > 0;
  if jsonb_array_length(v_blocked) > 0 then return jsonb_build_object('ok', false, 'reason', 'blocked', 'blocked', v_blocked); end if;
  v_ids := array(select c.id from public.hub_knowledge_cards c where (not c.is_test or internal.is_admin()) and internal.hub_card_pending(c) order by c.sort);
  if cardinality(v_ids) = 0 then return jsonb_build_object('ok', false, 'reason', 'nothing'); end if;
  v_gate := internal.hub_knowledge_gate_run(v_ids, p_eval_run);
  if not coalesce((v_gate ->> 'ok')::boolean, false) then return jsonb_build_object('ok', false, 'reason', 'gate', 'gate', v_gate, 'count', cardinality(v_ids)); end if;
  if p_dry_run then return jsonb_build_object('ok', true, 'dry_run', true, 'count', cardinality(v_ids), 'gate', v_gate); end if;
  v_batch := internal.begin_batch();
  update public.hub_knowledge_cards c set live = internal.hub_card_snapshot(c), status = 'published', published_at = now(), published_by = auth.uid(),
         first_published_at = coalesce(c.first_published_at, now()), updated_by = auth.uid()
   where c.id = any (v_ids);
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'count', cardinality(v_ids), 'gate', v_gate);
end;
$$;

-- ───────────────────────────────────────────── 4. the persona ─────────────────────────────────────────────

create trigger hub_units_persona_audit after update of persona, persona_live on public.hub_units
  for each row when (old.persona is distinct from new.persona or old.persona_live is distinct from new.persona_live)
  execute function internal.audit('key', 'persona', 'persona_live');

-- what is wrong with a persona: [{code, field}] — tone 1–5, emoji yes / no, the four greetings (≤ 160): no word that
-- presents the assistant, nothing forbidden, the singular address, Western digits, only {unit_name} / {first_name}
-- ({first_name} in the returning greetings only), no emoji unless allowed, Arabic in the Arabic ones
create function internal.hub_persona_problems(p jsonb) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v jsonb := '[]'::jsonb;
  f text;
  t text;
  v_term text;
begin
  if coalesce(jsonb_typeof(p -> 'tone'), '') <> 'number' or (p ->> 'tone')::numeric not in (1, 2, 3, 4, 5) then v := v || jsonb_build_object('code', 'tone', 'field', 'tone'); end if;
  if coalesce(jsonb_typeof(p -> 'emoji'), '') <> 'boolean' then v := v || jsonb_build_object('code', 'emoji', 'field', 'emoji'); end if;
  if exists (select 1 from jsonb_object_keys(p) k where k not in ('tone', 'emoji', 'greeting_new_ar', 'greeting_new_en', 'greeting_returning_ar', 'greeting_returning_en')) then
    v := v || jsonb_build_object('code', 'unknown_field', 'field', 'persona');
  end if;
  foreach f in array array['greeting_new_ar', 'greeting_new_en', 'greeting_returning_ar', 'greeting_returning_en'] loop
    t := btrim(coalesce(p ->> f, ''));
    if t = '' then v := v || jsonb_build_object('code', 'required', 'field', f); continue; end if;
    if char_length(t) > 160 then v := v || jsonb_build_object('code', 'too_long', 'field', f); end if;
    if t ~* '(^|[^[:alnum:]])(مساعد|المساعد|آلي|الآلي|بوت|روبوت|ذكاء اصطناعي|الذكاء الاصطناعي|assistant|bot|chatbot|ai|automated|virtual)([^[:alnum:]]|$)' then
      v := v || jsonb_build_object('code', 'self_description', 'field', f);
    end if;
    foreach v_term in array internal.hub_forbidden_terms() loop
      if strpos(lower(t), v_term) > 0 then v := v || jsonb_build_object('code', 'forbidden_term', 'field', f, 'term', v_term); end if;
    end loop;
    if t ~ '[٠-٩۰-۹]' then v := v || jsonb_build_object('code', 'indic_digits', 'field', f); end if;
    if exists (select 1 from regexp_matches(t, '\{([^}]*)\}', 'g') m where m[1] not in ('unit_name', 'first_name')) then v := v || jsonb_build_object('code', 'placeholder_unknown', 'field', f); end if;
    if f like 'greeting_new_%' and strpos(t, '{first_name}') > 0 then v := v || jsonb_build_object('code', 'first_name_new', 'field', f); end if;
    if not coalesce((p ->> 'emoji')::boolean, false) and t ~ '[\U0001F300-\U0001FAFF☀-➿]' then v := v || jsonb_build_object('code', 'emoji_off', 'field', f); end if;
    if f like '%_ar' and t !~ '[ء-ي]' then v := v || jsonb_build_object('code', 'language', 'field', f); end if;
    if f like '%_en' and t ~ '[ء-ي]' then v := v || jsonb_build_object('code', 'language', 'field', f); end if;
  end loop;
  return v;
end;
$$;

-- «حفظ» of «الشخصية» (assistant: edit in the unit's branch): the draft — the guests see it only after «نشر»
create function public.hub_persona_save(p_unit uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  u public.hub_units;
  v jsonb;
  v_batch uuid;
  v_p jsonb;
begin
  select * into u from public.hub_units where id = p_unit for update;
  if u.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if not internal.can('assistant', 'edit') or not internal.can_branch(u.branch_slug) then raise exception 'not allowed' using errcode = '42501'; end if;
  v_p := jsonb_build_object('tone', p -> 'tone', 'emoji', p -> 'emoji',
    'greeting_new_ar', btrim(coalesce(p ->> 'greeting_new_ar', '')), 'greeting_new_en', btrim(coalesce(p ->> 'greeting_new_en', '')),
    'greeting_returning_ar', btrim(coalesce(p ->> 'greeting_returning_ar', '')), 'greeting_returning_en', btrim(coalesce(p ->> 'greeting_returning_en', '')));
  v := internal.hub_persona_problems(v_p);
  if jsonb_array_length(v) > 0 then raise exception 'hub_persona_problems' using errcode = 'P0001', detail = v::text; end if;
  v_p := jsonb_set(v_p, '{tone}', to_jsonb((v_p ->> 'tone')::int));
  if v_p = u.persona then raise exception 'nothing to change' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  update public.hub_units set persona = v_p where id = u.id;
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'previous', u.persona, 'pending', v_p is distinct from u.persona_live);
end;
$$;

-- «نشر» of «الشخصية»: through a finished persona gate run of this unit on this draft (verdict pass, 24 hours)
create function public.hub_persona_publish(p_unit uuid, p_eval_run uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  u public.hub_units;
  run public.hub_eval_runs;
  v_batch uuid;
begin
  select * into u from public.hub_units where id = p_unit for update;
  if u.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if not internal.can('assistant', 'edit') or not internal.can_branch(u.branch_slug) then raise exception 'not allowed' using errcode = '42501'; end if;
  if u.persona is not distinct from u.persona_live or u.persona = '{}'::jsonb then return jsonb_build_object('ok', false, 'reason', 'nothing'); end if;
  if jsonb_array_length(internal.hub_persona_problems(u.persona)) > 0 then return jsonb_build_object('ok', false, 'reason', 'blocked', 'problems', internal.hub_persona_problems(u.persona)); end if;
  select * into run from public.hub_eval_runs where id = p_eval_run;
  if run.id is null or run.trigger <> 'persona' or run.candidate ->> 'unit' <> u.key then return jsonb_build_object('ok', false, 'reason', 'gate', 'gate', jsonb_build_object('gate', 'eval_required')); end if;
  if run.status in ('queued', 'running') then return jsonb_build_object('ok', false, 'reason', 'gate', 'gate', jsonb_build_object('gate', 'eval_running', 'run_id', run.id)); end if;
  if run.status <> 'done' or run.verdict is distinct from 'pass' then
    return jsonb_build_object('ok', false, 'reason', 'gate', 'gate', jsonb_build_object('gate', 'eval_blocked', 'run_id', run.id, 'blocked', run.blocked_items));
  end if;
  if run.finished_at < now() - interval '24 hours' or run.candidate ->> 'persona_hash' is distinct from md5(u.persona::text) then
    return jsonb_build_object('ok', false, 'reason', 'gate', 'gate', jsonb_build_object('gate', 'eval_stale', 'run_id', run.id));
  end if;
  v_batch := internal.begin_batch();
  update public.hub_units set persona_live = persona where id = u.id;
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'known_gaps', run.known_gaps);
end;
$$;

-- «المحاكي»'s context (as the user, assistant: edit in the unit's branch): the item context of hub_eval_context, the
-- unsaved persona applied by the function — and, with p_drafts, the pending cards to read as published
create function public.hub_sim_context(p_unit text, p_drafts boolean default false) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare u public.hub_units;
begin
  select * into u from public.hub_units where key = p_unit;
  if u.id is null then raise exception 'hub_unit' using errcode = '22023'; end if;
  if not internal.can('assistant', 'edit') or not internal.can_branch(u.branch_slug) then raise exception 'not allowed' using errcode = '42501'; end if;
  if u.knowledge_hidden or u.status <> 'active' then raise exception 'unit_hidden' using errcode = 'P0001'; end if;
  return public.hub_eval_context(p_unit) || jsonb_build_object('draft_cards', case when p_drafts then to_jsonb(internal.hub_pending_cards()) else '[]'::jsonb end,
                                                               'persona_draft', u.persona, 'budget', internal.hub_budget_state());
end;
$$;

-- «المحاكي»'s model calls into the budget (service role, hub-admin): source simulator, shown apart in «الميزانية»
create function public.hub_sim_usage(p_unit uuid, p_layer text, p_model text, p_in bigint, p_out bigint) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_cost numeric;
begin
  if p_layer not in ('understand', 'tag', 'compose') then raise exception 'hub_usage_layer' using errcode = '22023'; end if;
  v_cost := internal.hub_usage_add(p_unit, p_layer, 'simulator', p_model, p_in, p_out, false);
  return jsonb_build_object('ok', true, 'cost_usd', v_cost);
end;
$$;

-- ───────────────────────────────────────────── 5. licences ─────────────────────────────────────────────

-- «تفعيل الرد التلقائي» / «إيقاف الرد التلقائي» (spec §2.10): the system admin only, by hand, with a reason; a topic
-- «للفريق دائمًا» is never licensed; nothing else ever changes a licence
create or replace function public.hub_licence_set(p_unit uuid, p_topic text, p_mode text, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  l public.hub_licences;
  v_batch uuid;
begin
  if not internal.is_system_admin() then raise exception 'hub_system_admin_only' using errcode = 'P0001'; end if;
  if p_mode is null or p_mode not in ('shadow', 'auto', 'blocked') then raise exception 'hub_licence_mode' using errcode = '22023'; end if;
  if char_length(btrim(coalesce(p_reason, ''))) not between 3 and 300 then raise exception 'hub_reason' using errcode = '22023'; end if;
  select * into l from public.hub_licences where unit_id = p_unit and topic_key = p_topic for update;
  if l.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if p_mode <> 'blocked' and exists (select 1 from public.hub_topics t where t.key = p_topic and t.always_handoff) then
    raise exception 'hub_licence_always_handoff' using errcode = 'P0001';
  end if;
  if p_mode = l.mode then raise exception 'nothing to change' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  update public.hub_licences set mode = p_mode, since = now(), set_by = auth.uid(), reason = btrim(p_reason) where id = l.id;
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'previous', l.mode);
end;
$$;

-- «التراخيص» (assistant: view in the unit's branch): each topic's licence and, as information only, the last 30 days of
-- the unit's assistant replies on that topic (drafts, approved unedited and its share, edited, rejected, flagged wrong)
create function public.hub_licence_rows(p_unit uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare u public.hub_units;
begin
  select * into u from public.hub_units where id = p_unit;
  if u.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if not internal.can('assistant', 'view') or not internal.can_branch(u.branch_slug) then raise exception 'not allowed' using errcode = '42501'; end if;
  return jsonb_build_object(
    'unit', jsonb_build_object('id', u.id, 'key', u.key, 'name_ar', u.name_ar, 'mode', u.assistant_mode),
    'system_admin', internal.is_system_admin(),
    'lab', internal.hub_unit_lab(u),
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
        'topic', t.key, 'label_ar', t.label_ar, 'label_en', t.label_en, 'parent_key', t.parent_key, 'always_handoff', t.always_handoff,
        'mode', l.mode, 'since', l.since, 'set_by_name', (select s.full_name from public.staff s where s.user_id = l.set_by), 'reason', l.reason,
        'drafts', coalesce(c.drafts, 0), 'approved_unedited', coalesce(c.unedited, 0), 'edited', coalesce(c.edited, 0), 'rejected', coalesce(c.rejected, 0),
        'flagged_wrong', coalesce(c.flagged, 0),
        'approved_pct', case when coalesce(c.unedited, 0) + coalesce(c.edited, 0) + coalesce(c.rejected, 0) > 0
                             then round(100.0 * c.unedited / (c.unedited + c.edited + c.rejected)) end) order by t.sort, t.key)
      from public.hub_topics t
      join public.hub_licences l on l.topic_key = t.key and l.unit_id = u.id
      left join (
        select k as topic,
               count(*) filter (where m.status in ('pending_approval', 'rejected', 'superseded') or m.approved_by is not null) as drafts,
               count(*) filter (where m.approved_by is not null and m.status <> 'rejected' and not coalesce(m.edited_before_send, false)) as unedited,
               count(*) filter (where m.approved_by is not null and m.status <> 'rejected' and coalesce(m.edited_before_send, false)) as edited,
               count(*) filter (where m.status = 'rejected') as rejected,
               count(*) filter (where m.flagged_wrong_at is not null) as flagged
          from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id,
               lateral jsonb_array_elements_text(coalesce(m.payload -> 'topics', '[]'::jsonb)) k
         where c.unit_id = u.id and m.author = 'assistant' and m.direction = 'out' and not m.is_test and m.status <> 'test'
           and not coalesce((m.payload ->> 'notice')::boolean, false) and m.created_at > now() - interval '30 days'
         group by k) c on c.topic = t.key
     where t.status = 'active' and not t.is_test), '[]'::jsonb));
end;
$$;

-- POST hub-agent (the sweep or the alerts) from the database (pg_net; the Vault token) — a no-op where the URL is unknown
create function internal.hub_agent_post(p_action text) returns bigint
language plpgsql security definer set search_path = '' as $$
declare
  v_url text := internal.vault_value('job_sweep_url');
  v_token text := internal.vault_value('hub_agent_token');
begin
  if coalesce(v_url, '') = '' or coalesce(v_token, '') = '' or v_url !~ '/functions/v1/' then return null; end if;
  return net.http_post(
    url := regexp_replace(v_url, '/functions/v1/.*$', '/functions/v1/hub-agent'),
    body := jsonb_build_object('action', p_action),
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-armada-agent', v_token),
    timeout_milliseconds := 60000);
exception when others then
  return null;
end;
$$;

-- «إبلاغ: رد خاطئ» (inbox: edit in the unit): an assistant reply that was sent and was wrong — the counters, an entry in
-- «لم أعرف الإجابة» for the guest's question, one alert to Ahmed (the email to the active admins + «التنبيهات»). It never
-- changes a licence by itself.
create function public.hub_flag_wrong(p_message uuid, p_note text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  m public.hub_messages;
  c public.hub_conversations;
  t public.hub_turns;
  v_topics text[];
begin
  select * into m from public.hub_messages where id = p_message for update;
  if m.id is null or m.author <> 'assistant' or m.direction <> 'out' then raise exception 'not_found' using errcode = '22023'; end if;
  c := internal.hub_conv_edit(m.conversation_id);
  if m.status not in ('queued', 'accepted', 'sent', 'delivered', 'read') then raise exception 'hub_flag_not_sent' using errcode = 'P0001'; end if;
  if m.flagged_wrong_at is not null then return jsonb_build_object('ok', true, 'changed', false); end if;
  if p_note is not null and char_length(btrim(p_note)) > 500 then raise exception 'hub_note' using errcode = '22023'; end if;
  update public.hub_messages set flagged_wrong_at = now(), flagged_wrong_by = auth.uid() where id = m.id;
  v_topics := array(select jsonb_array_elements_text(coalesce(m.payload -> 'topics', '[]'::jsonb)));
  update public.hub_licences set flagged_wrong = flagged_wrong + 1 where unit_id = c.unit_id and topic_key = any (v_topics);
  select * into t from public.hub_turns where id = m.turn_id;
  if t.id is not null then perform internal.hub_unanswered_add(c, t.first_inbound_id, auth.uid(), v_topics[1]); end if;
  insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, actor_staff_id, reason, is_test)
  values (c.id, 'flag', null, 'wrong', auth.uid(), 'flagged_wrong', c.is_test);
  if nullif(btrim(coalesce(p_note, '')), '') is not null then
    insert into public.hub_messages (conversation_id, channel_id, direction, author, staff_id, kind, body, idempotency_key, status, sent_at, is_test)
    values (c.id, c.channel_id, 'out', 'staff', auth.uid(), 'note', btrim(p_note), 'flag:' || m.id, 'internal', now(), c.is_test)
    on conflict (idempotency_key) do nothing;
  end if;
  insert into public.hub_alerts (kind, unit_id, payload, is_test)
  values ('flagged_wrong', c.unit_id, jsonb_build_object('item', 'msg:' || m.id, 'message_id', m.id, 'conversation_id', c.id, 'topics', to_jsonb(v_topics)), c.is_test)
  on conflict do nothing;
  if not c.is_test then perform internal.hub_agent_post('alerts'); end if;
  return jsonb_build_object('ok', true, 'changed', true);
end;
$$;

-- the replies of a conversation already flagged wrong (inbox: view in the unit) — the inbox marks them
create function public.hub_flagged_in(p_conversation uuid) returns uuid[]
language sql stable security definer set search_path = '' as $$
  select coalesce(array_agg(m.id), '{}') from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id
   where m.conversation_id = p_conversation and m.flagged_wrong_at is not null and internal.can_unit(c.unit_id, 'view')
$$;

-- ───────────────────────────────────────────── 6. the radar ─────────────────────────────────────────────

alter table public.hub_turns add column topics text[] not null default '{}';
alter table public.hub_turns add column topic_hint text check (topic_hint is null or topic_hint ~ '^[a-z0-9][a-z0-9 _-]{1,59}$');
alter table public.hub_turns add column outcome text check (outcome is null or outcome in ('answered', 'handoff', 'unanswered', 'other'));
comment on column public.hub_turns.topics is 'Guest Hub H6: the topics of the understanding (codes) — kept when the understanding is purged after 12 months; the radar reads them.';
create index hub_turns_topics on public.hub_turns using gin (topics);
create index hub_turns_created on public.hub_turns (created_at);

-- the codes of a turn, from its understanding and its decision (the understanding itself stays unit-scoped)
create function internal.hub_turn_codes() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_hint text;
begin
  if new.understanding is not null then
    new.topics := array(select distinct x from jsonb_array_elements_text(case when jsonb_typeof(new.understanding -> 'topics') = 'array' then new.understanding -> 'topics' else '[]'::jsonb end) x
                         where x ~ '^[a-z0-9_]{2,60}$');
    v_hint := lower(btrim(coalesce(new.understanding ->> 'new_topic_hint', '')));
    new.topic_hint := case when v_hint ~ '^[a-z0-9][a-z0-9 _-]{1,59}$' then v_hint end;
  end if;
  if new.decision is not null then
    new.outcome := case
      when coalesce(new.decision ->> 'reason', '') = 'no_source' then 'unanswered'
      when new.decision ->> 'next' = 'human' or coalesce(new.decision -> 'actions', '[]'::jsonb) ? 'handoff' then 'handoff'
      when coalesce(new.decision -> 'actions', '[]'::jsonb) ?| array['answer', 'from_price', 'booking_status', 'fixed'] then 'answered'
      else 'other' end;
  end if;
  return new;
end;
$$;
create trigger hub_turns_codes before insert or update of understanding, decision on public.hub_turns for each row execute function internal.hub_turn_codes();
update public.hub_turns set understanding = understanding where understanding is not null or decision is not null;

create table public.hub_topic_hints (
  hint text primary key check (hint ~ '^[a-z0-9][a-z0-9 _-]{1,59}$'),
  status text not null check (status in ('accepted', 'merged', 'dismissed')),
  topic_key text references public.hub_topics (key) on update cascade on delete set null,
  decided_by uuid references auth.users (id) on delete set null,
  decided_at timestamptz not null default now(),
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger hub_topic_hints_touch before update on public.hub_topic_hints for each row execute function internal.stamp();
create trigger hub_topic_hints_audit after insert or update or delete on public.hub_topic_hints
  for each row execute function internal.audit('hint', 'status', 'topic_key');
alter table public.hub_topic_hints enable row level security;
revoke all on table public.hub_topic_hints from public, anon, authenticated;
grant select on table public.hub_topic_hints to authenticated;
grant all on table public.hub_topic_hints to service_role;
create policy hub_topic_hints_read on public.hub_topic_hints for select to authenticated using (internal.can('radar', 'view'));

-- «رادار الأسئلة» (radar: view): per topic for [p_from, p_to] (Riyadh dates) — asked, answered by the assistant, handed
-- off, unanswered, the previous period of the same length; samples of the questions only from units the caller's team
-- reads (internal.can_unit); the open spike alerts; the proposed topics (a new_topic_hint seen 3 times in 30 days).
-- Test rows never count; a turn of «تجربة» counts as asked only (the assistant answered nobody).
create function public.hub_radar(p_from date, p_to date, p_unit text default null, p_channel uuid default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_days integer;
  v_pfrom date;
  v_pto date;
  v_from timestamptz;
  v_to timestamptz;
  v_rows jsonb;
begin
  if not internal.can('radar', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 366 then raise exception 'hub_range' using errcode = '22023'; end if;
  v_days := p_to - p_from + 1;
  v_pto := p_from - 1;
  v_pfrom := p_from - v_days;
  v_from := (p_from::timestamp at time zone 'Asia/Riyadh');
  v_to := ((p_to + 1)::timestamp at time zone 'Asia/Riyadh');
  with scope as (
    select u.id, u.key from public.hub_units u where internal.can_branch(u.branch_slug) and not u.is_test and (p_unit is null or u.key = p_unit)
  ), turns as (
    select t.id, t.unit_id, t.mode, t.outcome, t.first_inbound_id, t.created_at, k as topic
      from public.hub_turns t join scope s on s.id = t.unit_id join public.hub_conversations c on c.id = t.conversation_id, unnest(t.topics) k
     where not t.is_test and t.created_at >= (v_pfrom::timestamp at time zone 'Asia/Riyadh') and t.created_at < v_to
       and (p_channel is null or c.channel_id = p_channel)
  ), cur as (
    select topic, count(*) as asked,
           count(*) filter (where mode in ('shadow', 'live') and outcome = 'answered') as answered,
           count(*) filter (where mode in ('shadow', 'live') and outcome in ('handoff', 'unanswered')) as handed_off
      from turns where created_at >= v_from group by topic
  ), prev as (
    select topic, count(*) as asked from turns where created_at < v_from group by topic
  ), una as (
    select q.topic_key as topic, count(*) as n from public.hub_unanswered q join scope s on s.id = q.unit_id
     where not q.is_test and q.created_at >= v_from and q.created_at < v_to and q.topic_key is not null group by q.topic_key
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'topic', t.key, 'label_ar', t.label_ar, 'label_en', t.label_en, 'parent_key', t.parent_key, 'always_handoff', t.always_handoff,
           'asked', coalesce(cur.asked, 0), 'answered', coalesce(cur.answered, 0), 'handed_off', coalesce(cur.handed_off, 0), 'unanswered', coalesce(una.n, 0),
           'previous', coalesce(prev.asked, 0),
           'trend_pct', case when coalesce(prev.asked, 0) > 0 then round(100.0 * (coalesce(cur.asked, 0) - prev.asked) / prev.asked) end,
           'spike', exists (select 1 from public.hub_alerts a where a.kind = 'spike' and a.acknowledged_at is null and not a.is_test and a.payload ->> 'topic' = t.key),
           'samples', coalesce((select jsonb_agg(z.e) from (
                         select left(btrim(regexp_replace(m.body, '\s+', ' ', 'g')), 200) as e
                           from turns x join public.hub_messages m on m.id = x.first_inbound_id
                          where x.topic = t.key and x.created_at >= v_from and m.body is not null and internal.can_unit(x.unit_id, 'view')
                          order by x.created_at desc limit 3) z), '[]'::jsonb))
         order by coalesce(cur.asked, 0) desc, coalesce(una.n, 0) desc, t.sort, t.key), '[]'::jsonb)
    into v_rows
    from public.hub_topics t left join cur on cur.topic = t.key left join prev on prev.topic = t.key left join una on una.topic = t.key
   where not t.is_test and t.status <> 'archived' and (coalesce(cur.asked, 0) + coalesce(prev.asked, 0) + coalesce(una.n, 0)) > 0;
  return jsonb_build_object(
    'from', p_from, 'to', p_to, 'previous_from', v_pfrom, 'previous_to', v_pto, 'rows', v_rows,
    'totals', (select jsonb_build_object('turns', count(*), 'with_topic', count(*) filter (where cardinality(t.topics) > 0))
                 from public.hub_turns t join public.hub_units u on u.id = t.unit_id join public.hub_conversations c on c.id = t.conversation_id
                where not t.is_test and internal.can_branch(u.branch_slug) and (p_unit is null or u.key = p_unit) and (p_channel is null or c.channel_id = p_channel)
                  and t.created_at >= v_from and t.created_at < v_to),
    'proposed', coalesce((select jsonb_agg(jsonb_build_object('hint', h.topic_hint, 'count', h.n, 'last_at', h.last_at) order by h.n desc, h.topic_hint)
                            from (select t.topic_hint, count(*) as n, max(t.created_at) as last_at from public.hub_turns t join public.hub_units u on u.id = t.unit_id
                                   where t.topic_hint is not null and not t.is_test and internal.can_branch(u.branch_slug) and t.created_at > now() - interval '30 days'
                                     and not exists (select 1 from public.hub_topic_hints d where d.hint = t.topic_hint)
                                     and not exists (select 1 from public.hub_topics x where x.key = replace(replace(t.topic_hint, ' ', '_'), '-', '_'))
                                   group by t.topic_hint having count(*) >= 3) h), '[]'::jsonb),
    'units', coalesce((select jsonb_agg(jsonb_build_object('key', u.key, 'name_ar', u.name_ar) order by u.sort, u.key) from public.hub_units u
                        where internal.can_branch(u.branch_slug) and not u.is_test and u.status = 'active'), '[]'::jsonb),
    'channels', coalesce((select jsonb_agg(jsonb_build_object('id', ch.id, 'unit', u.key, 'address', ch.address) order by u.sort, ch.created_at)
                           from public.hub_channels ch join public.hub_units u on u.id = ch.unit_id where internal.can_branch(u.branch_slug) and not ch.is_test), '[]'::jsonb),
    'can_decide', internal.can('knowledge', 'edit'),
    'spike', jsonb_build_object('factor', coalesce((select (s.value #>> '{}')::numeric from public.settings s where s.key = 'hub_spike_factor'), 3),
                                'min', internal.hub_setting_int('hub_spike_min', 5)));
end;
$$;

-- a proposed topic (knowledge: edit — the taxonomy is the knowledge base's): accept (a new topic, its licences shadow
-- by the H5 trigger), merge into an existing topic, or dismiss
create function public.hub_topic_hint_decide(p_hint text, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_action text := coalesce(p ->> 'action', '');
  v_key text := lower(btrim(coalesce(p ->> 'key', '')));
  v_batch uuid;
begin
  if not internal.can('knowledge', 'edit') then raise exception 'not allowed' using errcode = '42501'; end if;
  if p_hint is null or p_hint !~ '^[a-z0-9][a-z0-9 _-]{1,59}$' then raise exception 'hub_hint' using errcode = '22023'; end if;
  if exists (select 1 from public.hub_topic_hints d where d.hint = p_hint) then raise exception 'hub_hint_done' using errcode = '22023'; end if;
  if v_action not in ('accept', 'merge', 'dismiss') then raise exception 'hub_hint_action' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  if v_action = 'accept' then
    if v_key !~ '^[a-z0-9_]{2,60}$' then raise exception 'hub_topic_key' using errcode = '22023'; end if;
    if exists (select 1 from public.hub_topics t where t.key = v_key) then raise exception 'hub_topic_taken' using errcode = '22023'; end if;
    if char_length(btrim(coalesce(p ->> 'label_ar', ''))) not between 2 and 80 or char_length(btrim(coalesce(p ->> 'label_en', ''))) not between 2 and 80 then
      raise exception 'hub_topic_label' using errcode = '22023';
    end if;
    if nullif(p ->> 'parent_key', '') is not null and not exists (select 1 from public.hub_topics t where t.key = p ->> 'parent_key' and t.status = 'active') then
      raise exception 'hub_topic_parent' using errcode = '22023';
    end if;
    insert into public.hub_topics (key, label_ar, label_en, parent_key, created_from, status, sort)
    values (v_key, btrim(p ->> 'label_ar'), btrim(p ->> 'label_en'), nullif(p ->> 'parent_key', ''), 'queue', 'active', coalesce((select max(t.sort) + 1 from public.hub_topics t), 0));
    insert into public.hub_topic_hints (hint, status, topic_key, decided_by) values (p_hint, 'accepted', v_key, auth.uid());
  elsif v_action = 'merge' then
    if not exists (select 1 from public.hub_topics t where t.key = p ->> 'topic_key' and t.status = 'active') then raise exception 'hub_card_topic' using errcode = '22023'; end if;
    insert into public.hub_topic_hints (hint, status, topic_key, decided_by) values (p_hint, 'merged', p ->> 'topic_key', auth.uid());
  else
    insert into public.hub_topic_hints (hint, status, decided_by) values (p_hint, 'dismissed', auth.uid());
  end if;
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'key', case when v_action = 'accept' then v_key else p ->> 'topic_key' end);
end;
$$;

-- the spike alert (spec §5.7; hourly): a topic asked at least hub_spike_min times in the last 24 hours and more than
-- hub_spike_factor × its daily average of the 28 days before — one alert per topic per Riyadh day, then the email
create function public.hub_radar_tick(p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_factor numeric := coalesce((select (s.value #>> '{}')::numeric from public.settings s where s.key = 'hub_spike_factor'), 3);
  v_min integer := internal.hub_setting_int('hub_spike_min', 5);
  v_day text := to_char(p_now at time zone 'Asia/Riyadh', 'YYYY-MM-DD');
  v_new integer := 0;
  r record;
begin
  for r in
    select k as topic, count(*) filter (where t.created_at > p_now - interval '24 hours') as c24,
           count(*) filter (where t.created_at <= p_now - interval '24 hours') / 28.0 as avg_day
      from public.hub_turns t, unnest(t.topics) k
     where not t.is_test and t.created_at > p_now - interval '29 days' and t.created_at <= p_now
     group by k
  loop
    if r.c24 >= v_min and r.c24 > v_factor * r.avg_day then
      insert into public.hub_alerts (kind, payload) values ('spike', jsonb_build_object('item', 'topic:' || r.topic || ':' || v_day, 'topic', r.topic, 'count', r.c24, 'avg', round(r.avg_day, 2)))
      on conflict do nothing;
      if found then v_new := v_new + 1; end if;
    end if;
  end loop;
  -- a spike of an earlier day is closed
  update public.hub_alerts set acknowledged_at = p_now where kind = 'spike' and acknowledged_at is null and not is_test and payload ->> 'item' not like '%:' || v_day;
  if v_new > 0 then perform internal.hub_agent_post('alerts'); end if;
  return jsonb_build_object('ok', true, 'new', v_new);
end;
$$;
select cron.schedule('hub-radar', '17 * * * *', 'select public.hub_radar_tick()');

-- ───────────────────────────────────────────── 7. draft cards from staff replies ─────────────────────────────────────────────

create table public.hub_card_jobs (
  id uuid primary key default gen_random_uuid(),
  unanswered_id uuid not null references public.hub_unanswered (id) on delete cascade,
  cluster_id uuid not null,
  conversation_id uuid not null references public.hub_conversations (id) on delete cascade,
  unit_id uuid not null references public.hub_units (id) on delete cascade,
  staff_message_id uuid not null unique references public.hub_messages (id) on delete cascade,
  -- done = a draft card was written · empty = the reply held no general fact · rejected = the draft held a guest detail
  status text not null default 'pending' check (status in ('pending', 'running', 'done', 'empty', 'rejected', 'failed', 'skipped')),
  reason text check (reason is null or reason ~ '^[a-z_]{2,40}$'),
  card_id uuid references public.hub_knowledge_cards (id) on delete set null,
  attempts integer not null default 0,
  cost_usd numeric(12, 6) not null default 0,
  claimed_at timestamptz,
  finished_at timestamptz,
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
comment on table public.hub_card_jobs is 'Guest Hub H6 (Ahmed, 14 Nov 2026): a staff reply to a question in «لم أعرف الإجابة» → a draft knowledge card (prompts.md §7); never published by itself.';
create trigger hub_card_jobs_touch before update on public.hub_card_jobs for each row execute function internal.stamp();
create index hub_card_jobs_pending on public.hub_card_jobs (created_at) where status in ('pending', 'running');
alter table public.hub_card_jobs enable row level security;
revoke all on table public.hub_card_jobs from public, anon, authenticated;
grant all on table public.hub_card_jobs to service_role;

-- a job for an open entry of this conversation once a staff member answered after the guest's question (at most three
-- tries per cluster; none once a draft exists)
create function internal.hub_card_job_add(p_entry public.hub_unanswered, p_reply public.hub_messages) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  if p_entry.id is null or p_reply.id is null or p_entry.status <> 'open' or p_entry.draft_card_id is not null then return null; end if;
  if exists (select 1 from public.hub_card_jobs j where j.cluster_id = coalesce(p_entry.cluster_id, p_entry.id) and j.status = 'done') then return null; end if;
  if (select count(*) from public.hub_card_jobs j where j.cluster_id = coalesce(p_entry.cluster_id, p_entry.id)) >= 3 then return null; end if;
  insert into public.hub_card_jobs (unanswered_id, cluster_id, conversation_id, unit_id, staff_message_id, is_test)
  values (p_entry.id, coalesce(p_entry.cluster_id, p_entry.id), p_entry.conversation_id, p_entry.unit_id, p_reply.id, p_entry.is_test)
  on conflict (staff_message_id) do nothing
  returning id into v_id;
  return v_id;
end;
$$;

create function internal.hub_card_job_on_reply() returns trigger
language plpgsql security definer set search_path = '' as $$
declare e public.hub_unanswered;
begin
  if new.direction = 'out' and new.author in ('staff', 'phone') and new.kind = 'text' and coalesce(btrim(new.body), '') <> '' and new.status not in ('internal', 'failed') then
    select q.* into e from public.hub_unanswered q join public.hub_messages g on g.id = q.message_id
     where q.conversation_id = new.conversation_id and q.status = 'open' and q.draft_card_id is null and g.sent_at <= coalesce(new.sent_at, now())
     order by g.sent_at desc limit 1;
    if e.id is not null and internal.hub_card_job_add(e, new) is not null and not new.is_test then perform internal.hub_agent_post('sweep'); end if;
  end if;
  return null;
end;
$$;
create trigger hub_messages_card_job after insert on public.hub_messages for each row execute function internal.hub_card_job_on_reply();

-- a question marked after the staff member already answered it: the first staff reply after it
create function internal.hub_card_job_on_entry() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  g public.hub_messages;
  r public.hub_messages;
begin
  select * into g from public.hub_messages where id = new.message_id;
  select m.* into r from public.hub_messages m
   where m.conversation_id = new.conversation_id and m.direction = 'out' and m.author in ('staff', 'phone') and m.kind = 'text'
     and coalesce(btrim(m.body), '') <> '' and m.status not in ('internal', 'failed') and m.sent_at >= g.sent_at
   order by m.sent_at limit 1;
  if r.id is not null and internal.hub_card_job_add(new, r) is not null and not new.is_test then perform internal.hub_agent_post('sweep'); end if;
  return null;
end;
$$;
create trigger hub_unanswered_card_job after insert on public.hub_unanswered for each row execute function internal.hub_card_job_on_entry();

-- the next jobs (service role, hub-agent): the guest's question (the queue's excerpt), the staff reply, the staff
-- member's first name, the date, the topics and units the draft may name. Not at the budget cap.
create function public.hub_card_job_claim(p_limit integer default 3) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  b jsonb := internal.hub_budget_state();
  v_out jsonb;
  v_ids uuid[];
begin
  if coalesce((b ->> 'capped')::boolean, false) or coalesce((b ->> 'unset')::boolean, false) then return jsonb_build_object('jobs', '[]'::jsonb, 'reason', 'budget_cap'); end if;
  update public.hub_card_jobs set status = case when attempts >= 2 then 'failed' else 'pending' end, reason = case when attempts >= 2 then 'stuck' end
   where status = 'running' and claimed_at < now() - interval '4 minutes';
  with picked as (select j.id from public.hub_card_jobs j where j.status = 'pending' order by j.created_at limit least(greatest(coalesce(p_limit, 3), 1), 10) for update skip locked),
  upd as (update public.hub_card_jobs j set status = 'running', claimed_at = now(), attempts = attempts + 1 from picked where j.id = picked.id returning j.id)
  select coalesce(array_agg(upd.id), '{}') into v_ids from upd;
  select coalesce(jsonb_agg(jsonb_build_object(
           'job_id', j.id, 'unit_key', u.key, 'branch', u.branch_slug, 'language', coalesce(c.language, 'ar'),
           'question', q.question_excerpt, 'reply', m.body, 'topic_key', q.topic_key,
           'staff_first_name', case when m.author = 'phone' then null else nullif(split_part(btrim(coalesce(s.full_name, '')), ' ', 1), '') end,
           'date', to_char(coalesce(m.sent_at, m.created_at) at time zone 'Asia/Riyadh', 'YYYY-MM-DD'),
           'topics', (select coalesce(jsonb_agg(jsonb_build_object('key', t.key, 'label_en', t.label_en, 'label_ar', t.label_ar) order by t.sort, t.key), '[]')
                        from public.hub_topics t where t.status = 'active' and not t.always_handoff and not t.is_test),
           'units', (select coalesce(jsonb_agg(x.key order by x.sort), '[]') from public.hub_units x where x.status = 'active' and not x.knowledge_hidden and not x.is_test)) order by j.created_at), '[]'::jsonb)
    into v_out
    from public.hub_card_jobs j join public.hub_unanswered q on q.id = j.unanswered_id join public.hub_messages m on m.id = j.staff_message_id
    join public.hub_units u on u.id = j.unit_id join public.hub_conversations c on c.id = j.conversation_id
    left join public.staff s on s.user_id = m.staff_id
   where j.id = any (v_ids);
  return jsonb_build_object('jobs', v_out);
end;
$$;

-- the job's outcome (service role): the model call into the budget (layer draft_card, source staff); done → a DRAFT card
-- (never published), source «رد {name} في محادثة {date} — يحتاج اعتماد», the price apart in price_note, linked to every
-- open entry of the cluster. Its check (copy_problems, the forbidden list) is the card's own.
create function public.hub_card_job_finish(p_job uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  j public.hub_card_jobs;
  m jsonb;
  d jsonb := p -> 'draft';
  v_cost numeric := 0;
  v_status text := case when p ->> 'status' in ('done', 'empty', 'rejected', 'failed') then p ->> 'status' else 'failed' end;
  v_card public.hub_knowledge_cards;
  v_name text := nullif(btrim(coalesce(p ->> 'staff_first_name', '')), '');
  v_date date := coalesce(nullif(p ->> 'date', '')::date, internal.riyadh_today());
  v_topics text[];
  v_units text[];
begin
  select * into j from public.hub_card_jobs where id = p_job for update;
  if j.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if j.status <> 'running' then return jsonb_build_object('ok', false, 'reason', 'not_running'); end if;
  for m in select * from jsonb_array_elements(coalesce(p -> 'models', '[]'::jsonb)) loop
    if coalesce((m ->> 'input_tokens')::bigint, 0) + coalesce((m ->> 'output_tokens')::bigint, 0) > 0 then
      v_cost := v_cost + internal.hub_usage_add(j.unit_id, 'draft_card', 'staff', m ->> 'model', (m ->> 'input_tokens')::bigint, (m ->> 'output_tokens')::bigint, j.is_test);
    end if;
  end loop;
  if v_status = 'done' then
    if jsonb_typeof(d) <> 'object' then v_status := 'failed'; end if;
  end if;
  -- one draft per question: a later reply's draft is not written once the cluster has one
  if v_status = 'done' and exists (select 1 from public.hub_card_jobs x where x.cluster_id = j.cluster_id and x.status = 'done' and x.id <> j.id) then
    v_status := 'skipped';
  end if;
  if v_status = 'done' then
    v_topics := array(select distinct x from jsonb_array_elements_text(coalesce(d -> 'topic_keys', '[]'::jsonb)) x
                       where exists (select 1 from public.hub_topics t where t.key = x and t.status = 'active' and not t.always_handoff));
    v_units := array(select distinct x from jsonb_array_elements_text(coalesce(d -> 'unit_keys', '[]'::jsonb)) x
                      where exists (select 1 from public.hub_units u where u.key = x and u.status = 'active' and not u.knowledge_hidden));
    insert into public.hub_knowledge_cards (key, unit_keys, topic_keys, title_ar, title_en, text_ar, text_en, source, source_date, price_note, draft_origin, status, sort, is_test)
    values ('k-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 10), v_units, v_topics,
            left(btrim(coalesce(d ->> 'title_ar', '')), 120), left(btrim(coalesce(d ->> 'title_en', '')), 120),
            left(btrim(coalesce(d ->> 'text_ar', '')), 1200), left(btrim(coalesce(d ->> 'text_en', '')), 1200),
            'رد ' || coalesce(v_name, 'الفريق') || ' في محادثة ' || coalesce(nullif(btrim(coalesce(p ->> 'date_text', '')), ''), to_char(v_date, 'YYYY-MM-DD')) || ' — يحتاج اعتماد', v_date,
            nullif(left(btrim(coalesce(d ->> 'price_note', '')), 300), ''),
            jsonb_build_object('kind', 'staff_reply', 'job', j.id, 'unanswered', j.unanswered_id, 'cluster', j.cluster_id, 'date', v_date),
            'draft', coalesce((select max(x.sort) + 1 from public.hub_knowledge_cards x), 0), j.is_test)
    returning * into v_card;
    update public.hub_unanswered set draft_card_id = v_card.id where cluster_id = j.cluster_id and status = 'open';
  end if;
  update public.hub_card_jobs set status = v_status, reason = case when v_status = 'skipped' then 'has_draft' when p ->> 'reason' ~ '^[a-z_]{2,40}$' then p ->> 'reason' end, card_id = v_card.id,
         cost_usd = cost_usd + v_cost, finished_at = now()
   where id = j.id;
  return jsonb_build_object('ok', true, 'card_id', v_card.id, 'check', case when v_card.id is not null then internal.hub_card_check(v_card) end, 'cost_usd', v_cost);
end;
$$;

-- «لم أعرف الإجابة» (H4) + each cluster's draft card from a staff reply
create or replace function public.hub_unanswered_list(p_status text default 'open') returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_rows jsonb;
begin
  if not internal.can('knowledge', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  if p_status not in ('open', 'answered', 'dismissed') then raise exception 'hub_status' using errcode = '22023'; end if;
  select coalesce(jsonb_agg(x order by x ->> 'last_at' desc), '[]'::jsonb) into v_rows from (
    select jsonb_build_object(
             'id', g.cluster_id, 'count', count(*), 'topic_key', max(g.topic_key),
             'topic_label', (select t.label_ar from public.hub_topics t where t.key = max(g.topic_key)),
             'first_at', min(g.created_at), 'last_at', max(g.created_at),
             'units', (select jsonb_agg(distinct coalesce(v.name_ar, u.name_ar)) from public.hub_unanswered y join public.hub_units u on u.id = y.unit_id
                        left join public.dining_venues v on v.id = u.dining_venue_id where y.cluster_id = g.cluster_id and y.status = p_status),
             'excerpts', coalesce((select jsonb_agg(e) from (select distinct y.question_excerpt as e from public.hub_unanswered y
                                    where y.cluster_id = g.cluster_id and y.status = p_status and y.question_excerpt is not null and internal.can_unit(y.unit_id, 'view')
                                    limit 3) z), '[]'::jsonb),
             'hidden_excerpts', count(*) filter (where g.question_excerpt is not null and not internal.can_unit(g.unit_id, 'view')),
             'resolved_card_id', max(g.resolved_card_id::text), 'resolved_faq_id', max(g.resolved_faq_id::text), 'resolved_at', max(g.resolved_at),
             'draft_card', (select jsonb_build_object('id', k.id, 'key', k.key, 'title_ar', k.title_ar, 'title_en', k.title_en, 'source', k.source,
                                                      'price_note', k.price_note, 'status', k.status, 'problems', jsonb_array_length(internal.hub_card_check(k) -> 'missing'))
                              from public.hub_knowledge_cards k where k.id = (max(g.draft_card_id::text))::uuid and k.status <> 'archived'),
             'is_test', bool_or(g.is_test)) as x
      from public.hub_unanswered g
     where g.status = p_status and (not g.is_test or internal.is_admin())
     group by g.cluster_id
     limit 500) q;
  return jsonb_build_object('rows', v_rows,
    'open', (select count(distinct y.cluster_id) from public.hub_unanswered y where y.status = 'open' and (not y.is_test or internal.is_admin())));
end;
$$;

-- a FAQ draft from a card (content: edit) — «إنشاء بطاقة» from the radar with «وأضف مسودة للأسئلة الشائعة»
create function public.hub_faq_draft_from_card(p_card uuid, p_category text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_knowledge_cards;
  v_faq uuid;
  v_batch uuid;
begin
  if not internal.can('knowledge', 'edit') or not internal.can('content', 'edit') then raise exception 'not allowed' using errcode = '42501'; end if;
  if coalesce(p_category, '') not in ('booking', 'stay', 'branches', 'business') then raise exception 'faq_category' using errcode = '22023'; end if;
  select * into c from public.hub_knowledge_cards where id = p_card and status <> 'archived';
  if c.id is null or (c.is_test and not internal.is_admin()) then raise exception 'not_found' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  insert into public.faq_items (key, category, q_ar, q_en, a_ar, a_en, sort, created_by, updated_by, is_test)
  values ('hub-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 8), p_category, left(c.title_ar, 400), left(c.title_en, 400), left(c.text_ar, 3000), left(c.text_en, 3000),
          coalesce((select max(x.sort) + 1 from public.faq_items x), 0), auth.uid(), auth.uid(), c.is_test)
  returning id into v_faq;
  update public.hub_knowledge_cards set faq_item_id = v_faq, updated_by = auth.uid() where id = c.id;
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'faq_id', v_faq);
end;
$$;

-- ───────────────────────────────────────────── 8. the sweep and the overview ─────────────────────────────────────────────

-- every minute (H5) — now also when an eval item, a draft-card job or an alert email waits
create or replace function public.hub_agent_kick() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_due integer;
  v_lab integer;
  v_jobs integer;
  v_alerts integer;
  v_req bigint;
begin
  select count(*) into v_due from public.hub_turns t
   where (t.status = 'pending' and t.due_at <= now() - interval '20 seconds') or (t.status = 'running' and t.claimed_at < now() - interval '3 minutes');
  select count(*) into v_lab from public.hub_eval_results r join public.hub_eval_runs u on u.id = r.run_id
   where u.status in ('queued', 'running') and (r.status = 'pending' or (r.status = 'running' and r.claimed_at < now() - interval '4 minutes'));
  select count(*) into v_jobs from public.hub_card_jobs j where j.status = 'pending' or (j.status = 'running' and j.claimed_at < now() - interval '4 minutes');
  select count(*) into v_alerts from public.hub_alerts a where a.kind in ('flagged_wrong', 'spike') and a.sent_at is null and a.acknowledged_at is null and not a.is_test;
  if v_due + v_lab + v_jobs + v_alerts > 0 then v_req := internal.hub_agent_post('sweep'); end if;
  return jsonb_build_object('ok', true, 'due', v_due, 'lab', v_lab, 'jobs', v_jobs, 'alerts', v_alerts, 'request', v_req);
end;
$$;

-- «إعدادات المساعد» (H5) + each unit's draft persona and its latest full test-lab run
create or replace function public.hub_assistant_overview() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_all boolean := internal.all_branches();
begin
  if not internal.can('assistant', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  return jsonb_build_object(
    'can_edit', internal.can('assistant', 'edit'),
    'system_admin', internal.is_system_admin(),
    'all_branches', v_all,
    'engine_ready', internal.hub_engine_ready(),
    'inbox_ready', internal.hub_inbox_ready(),
    'budget', internal.hub_budget_state(),
    'units', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', u.id, 'key', u.key, 'kind', u.kind, 'name_ar', u.name_ar, 'name_en', u.name_en, 'branch', u.branch_slug, 'status', u.status,
        'mode', u.assistant_mode, 'skills', to_jsonb(u.skills), 'sort', u.sort, 'persona_published', u.persona_live is not null, 'persona', u.persona_live,
        'persona_draft', u.persona, 'persona_pending', u.persona is distinct from u.persona_live and u.persona <> '{}'::jsonb,
        'knowledge_hidden', u.knowledge_hidden, 'lab', internal.hub_unit_lab(u),
        'venue', (select jsonb_build_object('id', d.id, 'slug', d.slug, 'name_ar', d.name_ar, 'name_en', d.name_en, 'status', d.status, 'menu', d.menu)
                    from public.dining_venues d where d.id = u.dining_venue_id),
        'channels', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'kind', c.kind, 'address', c.address, 'waba_id', c.waba_id,
                                                                   'display_name', c.display_name, 'connected', c.connected, 'verified_at', c.verified_at,
                                                                   'provider_status', c.provider_status, 'quality_rating', c.quality_rating,
                                                                   'messaging_limit', c.messaging_limit, 'sending_enabled', c.sending_enabled) order by c.created_at)
                                from public.hub_channels c where c.unit_id = u.id), '[]'::jsonb),
        'members', coalesce((select jsonb_agg(jsonb_build_object('staff_id', s.user_id, 'full_name', s.full_name, 'role', s.role, 'branch', s.branch, 'active', s.active)
                                               order by s.full_name)
                               from public.hub_unit_members m join public.staff s on s.user_id = m.staff_id where m.unit_id = u.id), '[]'::jsonb),
        'gates', internal.hub_unit_gates_mode(u, 'test'),
        'gates_shadow', internal.hub_unit_gates_mode(u, 'shadow')) order by u.sort, u.key)
        from public.hub_units u where internal.can_branch(u.branch_slug) and (not u.is_test or internal.is_admin())), '[]'::jsonb),
    'staff', coalesce((select jsonb_agg(jsonb_build_object('staff_id', s.user_id, 'full_name', s.full_name, 'role', s.role, 'branch', s.branch) order by s.full_name)
                         from public.staff s where s.active and (s.branch is null or internal.can_branch(s.branch))), '[]'::jsonb),
    'settings', (select coalesce(jsonb_object_agg(s.key, s.value), '{}'::jsonb) from public.settings s where s.key = any(internal.hub_setting_keys())),
    'switch_gates', jsonb_build_object('hub_assistant_on', internal.hub_switch_gates('hub_assistant_on'), 'hub_inbox_on', internal.hub_switch_gates('hub_inbox_on')),
    'recipients', case when v_all then coalesce((
      select jsonb_agg(jsonb_build_object('id', r.id, 'email', r.email, 'active', r.active, 'filter_confirmed_at', r.filter_confirmed_at) order by r.created_at, r.email)
        from public.booking_notification_recipients r where r.scope = 'hub_summary'), '[]'::jsonb) else null end,
    'templates', coalesce((
      select jsonb_agg(jsonb_build_object('channel_id', t.channel_id, 'unit', u.key, 'name', t.name, 'language', t.language, 'category', t.category,
                                          'status', t.status, 'reason', t.reason, 'read_at', t.read_at) order by u.sort, t.name, t.language)
        from public.hub_templates t join public.hub_channels c on c.id = t.channel_id join public.hub_units u on u.id = c.unit_id
       where internal.can_branch(u.branch_slug) and not t.is_test), '[]'::jsonb),
    'alerts', coalesce((
      select jsonb_agg(jsonb_build_object('id', a.id, 'kind', a.kind, 'unit', u.key, 'payload', a.payload, 'created_at', a.created_at) order by a.created_at desc)
        from public.hub_alerts a left join public.hub_units u on u.id = a.unit_id
       where a.acknowledged_at is null and not a.is_test
         and ((a.unit_id is null and v_all) or (u.id is not null and internal.can_branch(u.branch_slug)))), '[]'::jsonb));
end;
$$;

-- ───────────────────────────────────────────── 9. privileges ─────────────────────────────────────────────

