  public.hub_topic_hint_decide(text, jsonb), public.hub_faq_draft_from_card(uuid, text), public.hub_knowledge_publish(boolean, uuid), public.hub_flagged_in(uuid)
  from public, anon;
grant execute on function public.hub_eval_plan(text, text, text), public.hub_eval_start(text, text, text), public.hub_eval_cancel(uuid),
  public.hub_eval_runs_list(integer), public.hub_eval_run(uuid), public.hub_test_items_list(), public.hub_test_item_save(uuid, jsonb),
  public.hub_test_item_retire(uuid, boolean), public.hub_test_item_gap(uuid, boolean, text), public.hub_persona_save(uuid, jsonb), public.hub_persona_publish(uuid, uuid),
  public.hub_sim_context(text, boolean), public.hub_licence_rows(uuid), public.hub_flag_wrong(uuid, text), public.hub_radar(date, date, text, uuid),
