grant execute on function public.hub_eval_claim(integer), public.hub_eval_context(text), public.hub_eval_finish(uuid, jsonb),
  public.hub_knowledge_for_eval(text, text[], text, text, uuid[]), public.hub_card_job_claim(integer), public.hub_card_job_finish(uuid, jsonb), public.hub_radar_tick(timestamptz),
  public.hub_sim_usage(uuid, text, text, bigint, bigint)
  to service_role;
